insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (162, 13, 1, 9, 'سورة الرعد ١ – ٩', 'آيات الله في الآفاق، وإنكار البعث، وعلم الله بما تحمل كل أنثى', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 162) = $j$[{"lbl": "الآيات ١ – ٤", "q": "الٓمٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِۗ وَٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ﴿١﴾ ٱللَّهُ ٱلَّذِي رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ يُدَبِّرُ ٱلۡأَمۡرَ يُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمۡ تُوقِنُونَ ﴿٢﴾ وَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنۡهَٰرٗاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٣﴾ وَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّـٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٤﴾", "w": [["المر", "هذه الحروف المقطعة تُكتب «المر» وتُقرأ: ألف، لام، ميم، را، والله أعلم بمراده بها."], ["بغير عمد ترونها", "العمد جمع عمود، أي: مرئية لكم."], ["ثم استوى على العرش", "استواءً يليق به عز وجل."], ["وسخّر الشمس والقمر", "ذلّلهما بمواصلة دورانهما لبقاء الحياة إلى أجلها."], ["هو الذي مدّ الأرض", "بسطها للحياة فوقها."], ["رواسي", "جبالاً ثوابت."], ["زوجين اثنين", "نوعين وضربين كالحلو والحامض، والأصفر والأسود مثلاً."], ["يُغشي الليل النهار", "يغطّيه حتى لا يبقى له وجود بالضياء."], ["قطع متجاورات", "بقاع متلاصقات."], ["ونخيل صنوان", "عدة نخلات في أصل واحد يجمعها."], ["في الأكل", "في الطعم: هذا حلو، وهذا مرّ، وهذا حامض."]], "m": "الله أعلم بمراده بـ«المر». تلك آيات الكتاب، والذي أُنزل إليك من ربك، وهو القرآن العظيم، هو الحق الثابت، ولكن أكثر الناس لا يؤمنون بأنه وحي الله فيعملوا به فيكملوا ويسعدوا. إن إلهكم الحق الذي يجب أن تعبدوه وتوحّدوه هو الله الذي رفع السماوات بغير عمد مرئية لكم، ثم استوى على عرشه استواءً يليق بذاته وجلاله يدبّر أمر الملكوت، وذلّل الشمس والقمر يجريان في فلكهما سيراً منتظماً إلى نهاية الحياة، يدبّر الأمر في السماوات والأرض بالإماتة والإحياء والمنع والإعطاء، ويفصّل الآيات القرآنية بذكر القصص وضرب الأمثال وبيان الحلال والحرام ليهيّئكم للإيمان بلقاء ربكم. وهو الذي بسط الأرض وجعل فيها جبالاً ثوابت وأنهاراً، ومن كل الثمرات جعل فيها نوعين: فالرمان منه الحلو والحامض، والزيتون منه الأصفر والأسود، ويغطّي النهار بالليل لتناموا وتستريح أبدانكم، إن في ذلك لآيات على وجوده وعلمه وقدرته ووجوب عبادته ولقائه. وفي الأرض بقاع متلاصقة: هذه تربتها طيبة، وهذه سبخة، وبساتين من أعناب وزرع ونخيل، منه ما يجتمع في أصل واحد ومنه ما يقوم على أصله، تُسقى بماء واحد ونفضّل بعضها على بعض في الطعم، إن في ذلك لآيات لقوم يعقلون، أما الذين أفسدت المادة والشهوة عقولهم فلا يدركون دلائل وجود الله فيؤمنون به ويعبدونه.", "h": ["تقرير عقيدة الوحي الإلهي ونبوة محمد ﷺ.", "تقرير عقيدة التوحيد، وأنه لا إله إلا الله.", "تقرير عقيدة البعث الآخر والجزاء على الكسب في الدنيا.", "فضيلة التفكر في الآيات الكونية.", "فضيلة العقل للاهتداء به إلى معرفة الحق واتباعه للإسعاد والإكمال."], "k": "«تُسقى بماء واحد ونفضّل بعضها على بعض في الأكل»… متى أكلت ثمرة آخر مرة وتفكّرت فيمن أخرجها؟"}, {"lbl": "الآيات ٥ – ٩", "q": "۞وَإِن تَعۡجَبۡ فَعَجَبٞ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقٖ جَدِيدٍۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ وَأُوْلَـٰٓئِكَ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَاقِهِمۡۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٥﴾ وَيَسۡتَعۡجِلُونَكَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن قَبۡلِهِمُ ٱلۡمَثُلَٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلۡعِقَابِ ﴿٦﴾ وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦٓۗ إِنَّمَآ أَنتَ مُنذِرٞۖ وَلِكُلِّ قَوۡمٍ هَادٍ ﴿٧﴾ ٱللَّهُ يَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلۡأَرۡحَامُ وَمَا تَزۡدَادُۚ وَكُلُّ شَيۡءٍ عِندَهُۥ بِمِقۡدَارٍ ﴿٨﴾ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡكَبِيرُ ٱلۡمُتَعَالِ ﴿٩﴾", "w": [["وإن تعجب", "يأخذك العجب من إنكارهم نبوّتك والتوحيد."], ["فعجب قولهم", "فاعجب منه إنكارهم للبعث والحياة الثانية مع وضوح الأدلة."], ["لفي خلق جديد", "نرجع كما كنا بشراً أحياء."], ["الأغلال في أعناقهم", "موانع من الإيمان والاهتداء في الدنيا، وأغلال تُشدّ بها أيديهم إلى أعناقهم في الآخرة."], ["بالسيئة", "بالعذاب."], ["قبل الحسنة", "قبل الرحمة والعافية والرخاء والخصب."], ["المثلات", "العقوبات التي أصابت المكذّبين في الأمم، واحدها مَثُلة."], ["لولا أُنزل عليه", "هلّا أُنزل عليه، و«لولا» أداة تحضيض."], ["آية من ربه", "معجزة كعصا موسى وناقة صالح."], ["ولكل قوم هاد", "نبي يدعوهم إلى ربهم ليعبدوه وحده."], ["ما تحمل كل أنثى", "من ذكر أو أنثى، واحداً أو أكثر."], ["وما تغيض الأرحام", "ما تنقص من دم الحيض، وما تزداد منه."]], "m": "ما زال السياق في دعوة المشركين إلى الإيمان بالتوحيد والنبوة والبعث: وإن تعجب يا نبينا من عدم إيمانهم برسالتك وتوحيد ربك، فعجب أكبر إنكارهم البعث إذ قالوا: أإذا كنا تراباً أإنا لفي خلق جديد؟ أولئك الذين كفروا بربهم، وأولئك الأغلال في أعناقهم: في الدنيا موانع الهداية كالتقليد الأعمى والكبر والعناد، وفي الآخرة أغلال من حديد، وأولئك أصحاب النار هم فيها خالدون. ويستعجلونك بالعذاب قبل العافية استخفافاً وجهلاً، وقد مضت العقوبات في الأمم قبلهم كعاد وثمود، فأين ذهبت عقولهم؟ وإن ربك لذو مغفرة للناس على ظلمهم، ولو كان يؤاخذ بالظلم لمجرد وقوعه ما ترك على الأرض من دابة، وإن ربك لشديد العقاب لمن عصاه بعد الإنذار. ويقول الكافرون: هلّا أُنزل عليه آية كعصا موسى! إنما أنت منذر، وليس لازماً أن تنزل معك الآيات، فاستمرّ على دعوتك، ولكل قوم هاد وأنت هادي هذه الأمة. الله يعلم ما تحمل كل أنثى: ذكراً أو أنثى، واحداً أو اثنين، سعيداً أو شقياً، ويعلم ما تنقص الأرحام وما تزداد، وكل شيء عنده بمقدار لا يزيد ولا ينقص، عالم الغيب والشهادة، الكبير الذي كل كبير أمامه صغير، المتعال على خلقه، فهل يليق بعاقل أن ينكر عليه أن يحيي العباد بعد أن يميتهم؟", "h": ["تقرير أصول العقيدة الثلاثة: التوحيد، والنبوة، والبعث والجزاء الآخر.", "صوارف الإيمان، والتي هي كالأغلال، هي التقليد الأعمى، والكبر والعناد.", "عظيم قدرة الله تعالى وسعة علمه.", "تقرير عقيدة القضاء والقدر."], "k": "«وإن ربك لذو مغفرة للناس على ظلمهم»… كم ذنب ستره ربي ولم يعاجلني به؛ فهل أشكر حلمه بالتوبة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 162;
insert into public.tdb_cards(topic, i, body) select 162, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "الٓمٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِۗ وَٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ﴿١﴾ ٱللَّهُ ٱلَّذِي رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدٖ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ يُدَبِّرُ ٱلۡأَمۡرَ يُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمۡ تُوقِنُونَ ﴿٢﴾ وَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنۡهَٰرٗاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٣﴾ وَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّـٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٤﴾", "w": [["المر", "هذه الحروف المقطعة تُكتب «المر» وتُقرأ: ألف، لام، ميم، را، والله أعلم بمراده بها."], ["بغير عمد ترونها", "العمد جمع عمود، أي: مرئية لكم."], ["ثم استوى على العرش", "استواءً يليق به عز وجل."], ["وسخّر الشمس والقمر", "ذلّلهما بمواصلة دورانهما لبقاء الحياة إلى أجلها."], ["هو الذي مدّ الأرض", "بسطها للحياة فوقها."], ["رواسي", "جبالاً ثوابت."], ["زوجين اثنين", "نوعين وضربين كالحلو والحامض، والأصفر والأسود مثلاً."], ["يُغشي الليل النهار", "يغطّيه حتى لا يبقى له وجود بالضياء."], ["قطع متجاورات", "بقاع متلاصقات."], ["ونخيل صنوان", "عدة نخلات في أصل واحد يجمعها."], ["في الأكل", "في الطعم: هذا حلو، وهذا مرّ، وهذا حامض."]], "m": "الله أعلم بمراده بـ«المر». تلك آيات الكتاب، والذي أُنزل إليك من ربك، وهو القرآن العظيم، هو الحق الثابت، ولكن أكثر الناس لا يؤمنون بأنه وحي الله فيعملوا به فيكملوا ويسعدوا. إن إلهكم الحق الذي يجب أن تعبدوه وتوحّدوه هو الله الذي رفع السماوات بغير عمد مرئية لكم، ثم استوى على عرشه استواءً يليق بذاته وجلاله يدبّر أمر الملكوت، وذلّل الشمس والقمر يجريان في فلكهما سيراً منتظماً إلى نهاية الحياة، يدبّر الأمر في السماوات والأرض بالإماتة والإحياء والمنع والإعطاء، ويفصّل الآيات القرآنية بذكر القصص وضرب الأمثال وبيان الحلال والحرام ليهيّئكم للإيمان بلقاء ربكم. وهو الذي بسط الأرض وجعل فيها جبالاً ثوابت وأنهاراً، ومن كل الثمرات جعل فيها نوعين: فالرمان منه الحلو والحامض، والزيتون منه الأصفر والأسود، ويغطّي النهار بالليل لتناموا وتستريح أبدانكم، إن في ذلك لآيات على وجوده وعلمه وقدرته ووجوب عبادته ولقائه. وفي الأرض بقاع متلاصقة: هذه تربتها طيبة، وهذه سبخة، وبساتين من أعناب وزرع ونخيل، منه ما يجتمع في أصل واحد ومنه ما يقوم على أصله، تُسقى بماء واحد ونفضّل بعضها على بعض في الطعم، إن في ذلك لآيات لقوم يعقلون، أما الذين أفسدت المادة والشهوة عقولهم فلا يدركون دلائل وجود الله فيؤمنون به ويعبدونه.", "h": ["تقرير عقيدة الوحي الإلهي ونبوة محمد ﷺ.", "تقرير عقيدة التوحيد، وأنه لا إله إلا الله.", "تقرير عقيدة البعث الآخر والجزاء على الكسب في الدنيا.", "فضيلة التفكر في الآيات الكونية.", "فضيلة العقل للاهتداء به إلى معرفة الحق واتباعه للإسعاد والإكمال."], "k": "«تُسقى بماء واحد ونفضّل بعضها على بعض في الأكل»… متى أكلت ثمرة آخر مرة وتفكّرت فيمن أخرجها؟"}, {"lbl": "الآيات ٥ – ٩", "q": "۞وَإِن تَعۡجَبۡ فَعَجَبٞ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقٖ جَدِيدٍۗ أُوْلَـٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ وَأُوْلَـٰٓئِكَ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَاقِهِمۡۖ وَأُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٥﴾ وَيَسۡتَعۡجِلُونَكَ بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن قَبۡلِهِمُ ٱلۡمَثُلَٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلۡعِقَابِ ﴿٦﴾ وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦٓۗ إِنَّمَآ أَنتَ مُنذِرٞۖ وَلِكُلِّ قَوۡمٍ هَادٍ ﴿٧﴾ ٱللَّهُ يَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلۡأَرۡحَامُ وَمَا تَزۡدَادُۚ وَكُلُّ شَيۡءٍ عِندَهُۥ بِمِقۡدَارٍ ﴿٨﴾ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡكَبِيرُ ٱلۡمُتَعَالِ ﴿٩﴾", "w": [["وإن تعجب", "يأخذك العجب من إنكارهم نبوّتك والتوحيد."], ["فعجب قولهم", "فاعجب منه إنكارهم للبعث والحياة الثانية مع وضوح الأدلة."], ["لفي خلق جديد", "نرجع كما كنا بشراً أحياء."], ["الأغلال في أعناقهم", "موانع من الإيمان والاهتداء في الدنيا، وأغلال تُشدّ بها أيديهم إلى أعناقهم في الآخرة."], ["بالسيئة", "بالعذاب."], ["قبل الحسنة", "قبل الرحمة والعافية والرخاء والخصب."], ["المثلات", "العقوبات التي أصابت المكذّبين في الأمم، واحدها مَثُلة."], ["لولا أُنزل عليه", "هلّا أُنزل عليه، و«لولا» أداة تحضيض."], ["آية من ربه", "معجزة كعصا موسى وناقة صالح."], ["ولكل قوم هاد", "نبي يدعوهم إلى ربهم ليعبدوه وحده."], ["ما تحمل كل أنثى", "من ذكر أو أنثى، واحداً أو أكثر."], ["وما تغيض الأرحام", "ما تنقص من دم الحيض، وما تزداد منه."]], "m": "ما زال السياق في دعوة المشركين إلى الإيمان بالتوحيد والنبوة والبعث: وإن تعجب يا نبينا من عدم إيمانهم برسالتك وتوحيد ربك، فعجب أكبر إنكارهم البعث إذ قالوا: أإذا كنا تراباً أإنا لفي خلق جديد؟ أولئك الذين كفروا بربهم، وأولئك الأغلال في أعناقهم: في الدنيا موانع الهداية كالتقليد الأعمى والكبر والعناد، وفي الآخرة أغلال من حديد، وأولئك أصحاب النار هم فيها خالدون. ويستعجلونك بالعذاب قبل العافية استخفافاً وجهلاً، وقد مضت العقوبات في الأمم قبلهم كعاد وثمود، فأين ذهبت عقولهم؟ وإن ربك لذو مغفرة للناس على ظلمهم، ولو كان يؤاخذ بالظلم لمجرد وقوعه ما ترك على الأرض من دابة، وإن ربك لشديد العقاب لمن عصاه بعد الإنذار. ويقول الكافرون: هلّا أُنزل عليه آية كعصا موسى! إنما أنت منذر، وليس لازماً أن تنزل معك الآيات، فاستمرّ على دعوتك، ولكل قوم هاد وأنت هادي هذه الأمة. الله يعلم ما تحمل كل أنثى: ذكراً أو أنثى، واحداً أو اثنين، سعيداً أو شقياً، ويعلم ما تنقص الأرحام وما تزداد، وكل شيء عنده بمقدار لا يزيد ولا ينقص، عالم الغيب والشهادة، الكبير الذي كل كبير أمامه صغير، المتعال على خلقه، فهل يليق بعاقل أن ينكر عليه أن يحيي العباد بعد أن يميتهم؟", "h": ["تقرير أصول العقيدة الثلاثة: التوحيد، والنبوة، والبعث والجزاء الآخر.", "صوارف الإيمان، والتي هي كالأغلال، هي التقليد الأعمى، والكبر والعناد.", "عظيم قدرة الله تعالى وسعة علمه.", "تقرير عقيدة القضاء والقدر."], "k": "«وإن ربك لذو مغفرة للناس على ظلمهم»… كم ذنب ستره ربي ولم يعاجلني به؛ فهل أشكر حلمه بالتوبة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (163, 13, 10, 18, 'سورة الرعد ١٠ – ١٨', '«إن الله لا يغيّر ما بقوم حتى يغيّروا ما بأنفسهم»، ودعوة الحق، ومثل الحق والباطل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 163) = $j$[{"lbl": "الآيات ١٠ – ١٣", "q": "سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّيۡلِ وَسَارِبُۢ بِٱلنَّهَارِ ﴿١٠﴾ لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ ﴿١١﴾ هُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ ﴿١٢﴾ وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَـٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ ﴿١٣﴾", "w": [["وسارب بالنهار", "ظاهر في سَرَبه، أي طريقه."], ["له معقبات", "ملائكة تتعقّبه بالليل والنهار."], ["من أمر الله", "بأمر الله تعالى، وعن إذنه وأمره."], ["لا يغيّر ما بقوم", "من عافية ونعمة إلى بلاء وعذاب."], ["ما بأنفسهم", "من طهر وصفاء بالإيمان والطاعات، إلى الذنوب والآثام."], ["وما لهم من دونه من وال", "ليس لهم من دون الله من يلي أمرهم فيدفع عنهم العذاب."], ["من خيفته", "من الخوف منه، وهيبته وجلاله."], ["وهو شديد المحال", "القوة والمماحلة."]], "m": "ما زال السياق في ذكر جلال الله وعظيم قدرته وسعة علمه: سواء منكم من أسرّ القول ومن جهر به، فالله يعلم السر وأخفى، ومن هو مستخفٍ بالليل في ظلامه، ومن هو ظاهر يمشي في طريقه بالنهار. له ملائكة يتعاقبون عليه من بين يديه ومن خلفه يحفظونه بأمر الله، ومنهم الكتبة للحسنات والسيئات. إن الله لا يزيل نعمة أنعم بها على قوم، من عافية وأمن ورخاء بسبب إيمانهم وصالح أعمالهم، حتى يغيّروا ما بأنفسهم من طهارة وصفاء بارتكاب الذنوب نتيجة الإعراض عن كتاب الله وتعطيل حدوده والانغماس في الشهوات. وإذا أراد الله بقوم سوءاً فلا مردّ له، وما لهم من دونه من وال يصرفه عنهم، أما إذا أنابوا إليه وتابوا فإنه يكشف عنهم السوء. هو الذي يريكم البرق خوفاً من الصواعق وطمعاً في المطر، وينشئ السحاب المثقل بالأمطار، ويسبّح الرعد بحمده، وهو ملك موكّل بالسحاب، والملائكة من خيفته وهيبته، ويرسل الصواعق فيصيب بها من يشاء وهم يجادلون في الله، في وجوده وصفاته وتوحيده، وهو شديد القوة والأخذ والبطش، وقد نزلت في رجل بعث إليه رسول الله ﷺ من يدعوه إلى الإسلام فقال: وما الله، أمن ذهب هو أم من فضة؟ فنزلت عليه صاعقة أثناء كلامه فأهلكته.", "h": ["سعة علم الله تعالى.", "الحرس والجلاوزة لمن يستخدمهم لحفظه من أمر الله تعالى لن يغنوا عنه من أمر الله شيئاً.", "تقرير عقيدة أن لكل فرد ملائكة يتعاقبون عليه بالليل والنهار، منهم الكرام الكاتبون، ومنهم الحفظة للإنسان من الشياطين والجان.", "بيان سنة أن النعم لا تزول إلا بالمعاصي.", "استحباب قول: «سبحان من يسبّح الرعد بحمده والملائكة من خيفته» عند سماع الرعد، لورود ذلك عن النبي ﷺ بألفاظ مختلفة."], "k": "«حتى يغيّروا ما بأنفسهم»… نعمة أخاف زوالها؛ فهل أحرسها بالطاعة أم أعرّضها بالمعصية؟"}, {"lbl": "الآيات ١٤ – ١٦", "q": "لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَجِيبُونَ لَهُم بِشَيۡءٍ إِلَّا كَبَٰسِطِ كَفَّيۡهِ إِلَى ٱلۡمَآءِ لِيَبۡلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦۚ وَمَا دُعَآءُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ﴿١٤﴾ وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩ ﴿١٥﴾ قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعٗا وَلَا ضَرّٗاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِي ٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ ٱلۡخَلۡقُ عَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّـٰرُ ﴿١٦﴾", "w": [["له دعوة الحق", "لله تعالى الدعوة الحق، فهو الإله الحق الذي لا إله إلا هو."], ["ليبلغ فاه", "ليبلغ الماء فمه."], ["إلا في ضلال", "في ضياع لا حصول منه على طائل."], ["بالغدو والآصال", "بالبُكَر جمع بُكرة، والعشايا جمع عشية."]], "m": "ما زال السياق في تقرير التوحيد بالأدلة: لله الدعوة الحق، فهو الإله الحق الذي لا إله إلا هو، أما غيره من الأصنام والأوثان وكل ما عُبد من دون الله فإطلاق لفظ إله عليه باطل، والدعوة إلى عبادته باطلة. والذين يدعونهم من دون الله لا يستجيبون لهم بشيء مما يطلبون منهم، إلا كاستجابة الماء لمن بسط كفيه إليه ليبلغ فاه وما هو ببالغه، فلا يصل إلى فمه وهو عطشان، فكذلك من يدعو غير الله لا يحصل منه على شيء، وما دعاء الكافرين إلا في ضياع وخسران. ولله يسجد من في السماوات من الملائكة، ومن في الأرض من المؤمنين طوعاً، والكافرون والمنافقون إذا أُكرهوا يسجدون كرهاً، وظلالهم تسجد في البكر والعشايا، وكلهم منقادون لقضاء الله وحكمه لا يستطيعون الخروج عنه. قل: من رب السماوات والأرض؟ قل: الله، إذ لا جواب لهم إلا هو، أفاتخذتم من دونه أولياء لا يملكون لأنفسهم نفعاً ولا ضراً؟ هل يستوي الأعمى والبصير، أم تستوي الظلمات والنور؟ فكيف يستوي المؤمن يعبد الله على بصيرة، والمشرك يعبد ما لا يسمع نداءً ولا يجيب دعاءً؟ أم جعلوا لله شركاء خلقوا كخلقه فتشابه الخلق عليهم؟ لا، فإنها لم تخلق شيئاً، قل: الله خالق كل شيء، وهو الواحد القهار المستحق للعبادة.", "h": ["دعوة الحق لله وحده، فهو المعبود بحق، لا إله غيره ولا رب سواه.", "خيبة المشركين في دعائهم وسائر عباداتهم.", "الخلق كلهم يسجدون لله طوعاً أو كرهاً، إذ الكل خاضع لحكم الله وتدبيره فيه.", "مشروعية السجود للقارئ والمستمع إذا بلغ هذه الآية: «وظلالهم بالغدو والآصال»، ويستحب أن يكون طاهراً مستقبلاً القبلة، ويكبّر عند الخفض والرفع ولا يسلّم.", "بطلان الشرك، إذ لا دليل عليه من عقل ولا نقل.", "وجوب العبادة لله تعالى."], "k": "«كباسط كفيه إلى الماء ليبلغ فاه»… لمن أمدّ يدي حين أحتاج: لمخلوق عاجز، أم للحي القيوم؟"}, {"lbl": "الآيتان ١٧ – ١٨", "q": "أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ ﴿١٧﴾ لِلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ أُوْلَـٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ﴿١٨﴾", "w": [["فسالت أودية بقدرها", "بمقدار مائها الذي يجري فيها."], ["زبداً رابياً", "غثاءً عالياً، إذ الزبد وضر غليان الماء أو جريانه."], ["ومما يوقدون عليه في النار", "كالذهب والفضة والنحاس."], ["ابتغاء حلية أو متاع", "طلباً لحلية من ذهب أو فضة، أو متاع من الأواني."], ["فيذهب جفاءً", "باطلاً مرمياً به بعيداً، إذ هو غثاء لا خير فيه."], ["فيمكث في الأرض", "يبقى في الأرض زمناً ينتفع به الناس."], ["للذين استجابوا لربهم الحسنى", "للذين آمنوا وعملوا الصالحات الجنة."], ["سوء الحساب", "المؤاخذة بكل ذنب عملوه، لا يُغفر لهم منه شيء."], ["وبئس المهاد", "الفراش الذي أعدّوه لأنفسهم، وهو جهنم."]], "m": "ضرب الله مثلاً للحق في بقائه، وللباطل في اضمحلاله: أنزل من السماء ماءً فسالت أودية بقدرها، بحسب كبرها وصغرها، فحمل السيل زبداً عالياً على سطح الماء، هذا مثل مائي. ومثل ناري: ومما يوقد عليه الصاغة والحدادون طلباً للحلية أو للمتاع كالأواني، يعلو ما كان فاسداً على صورة الزبد، ويبقى الصالح في البوتقة. كذلك يضرب الله الحق والباطل: فأما الزبد فيذهب باطلاً مرمياً به، يرميه السيل إلى ساحل الوادي ويرميه الصائغ عن بوتقته، وأما ما ينفع الناس من الماء والحلي والمتاع فيمكث ويبقى، كذلك يبيّن الله الأمثال ليعلموا فيؤمنوا ويهتدوا، فالحق باقٍ والباطل ذاهب وإن علا وطغا في بعض الأوقات. ثم أخبر بوعده ووعيده: للذين استجابوا لربهم بالإيمان والطاعة الحسنى، الجنة، والذين لم يستجيبوا لو أن لهم ما في الأرض جميعاً ومثله معه لافتدوا به من العذاب، أولئك لهم سوء الحساب، يحاسبون على كل صغيرة وكبيرة ولا يُغفر لهم منها شيء، ومأواهم جهنم وبئس الفراش.", "h": ["استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان.", "ثبات الحق، واضمحلال الباطل سنة من سنن الله تعالى.", "بيان وعد الله للمستجيبين له بالإيمان والطاعة، وهو الجنة.", "بيان وعيد الله لمن لم يستجب له بالإيمان والطاعة."], "k": "«فأما الزبد فيذهب جفاءً»… الباطل يعلو ثم يذهب؛ فهل أثبت على الحق وإن بدا الباطل غالباً؟"}]$j$::jsonb then 0 else 1 end;
