insert into public.tdb_cards(topic, i, body) select 163, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠ – ١٣", "q": "سَوَآءٞ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّيۡلِ وَسَارِبُۢ بِٱلنَّهَارِ ﴿١٠﴾ لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ ﴿١١﴾ هُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ ﴿١٢﴾ وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَـٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ ﴿١٣﴾", "w": [["وسارب بالنهار", "ظاهر في سَرَبه، أي طريقه."], ["له معقبات", "ملائكة تتعقّبه بالليل والنهار."], ["من أمر الله", "بأمر الله تعالى، وعن إذنه وأمره."], ["لا يغيّر ما بقوم", "من عافية ونعمة إلى بلاء وعذاب."], ["ما بأنفسهم", "من طهر وصفاء بالإيمان والطاعات، إلى الذنوب والآثام."], ["وما لهم من دونه من وال", "ليس لهم من دون الله من يلي أمرهم فيدفع عنهم العذاب."], ["من خيفته", "من الخوف منه، وهيبته وجلاله."], ["وهو شديد المحال", "القوة والمماحلة."]], "m": "ما زال السياق في ذكر جلال الله وعظيم قدرته وسعة علمه: سواء منكم من أسرّ القول ومن جهر به، فالله يعلم السر وأخفى، ومن هو مستخفٍ بالليل في ظلامه، ومن هو ظاهر يمشي في طريقه بالنهار. له ملائكة يتعاقبون عليه من بين يديه ومن خلفه يحفظونه بأمر الله، ومنهم الكتبة للحسنات والسيئات. إن الله لا يزيل نعمة أنعم بها على قوم، من عافية وأمن ورخاء بسبب إيمانهم وصالح أعمالهم، حتى يغيّروا ما بأنفسهم من طهارة وصفاء بارتكاب الذنوب نتيجة الإعراض عن كتاب الله وتعطيل حدوده والانغماس في الشهوات. وإذا أراد الله بقوم سوءاً فلا مردّ له، وما لهم من دونه من وال يصرفه عنهم، أما إذا أنابوا إليه وتابوا فإنه يكشف عنهم السوء. هو الذي يريكم البرق خوفاً من الصواعق وطمعاً في المطر، وينشئ السحاب المثقل بالأمطار، ويسبّح الرعد بحمده، وهو ملك موكّل بالسحاب، والملائكة من خيفته وهيبته، ويرسل الصواعق فيصيب بها من يشاء وهم يجادلون في الله، في وجوده وصفاته وتوحيده، وهو شديد القوة والأخذ والبطش، وقد نزلت في رجل بعث إليه رسول الله ﷺ من يدعوه إلى الإسلام فقال: وما الله، أمن ذهب هو أم من فضة؟ فنزلت عليه صاعقة أثناء كلامه فأهلكته.", "h": ["سعة علم الله تعالى.", "الحرس والجلاوزة لمن يستخدمهم لحفظه من أمر الله تعالى لن يغنوا عنه من أمر الله شيئاً.", "تقرير عقيدة أن لكل فرد ملائكة يتعاقبون عليه بالليل والنهار، منهم الكرام الكاتبون، ومنهم الحفظة للإنسان من الشياطين والجان.", "بيان سنة أن النعم لا تزول إلا بالمعاصي.", "استحباب قول: «سبحان من يسبّح الرعد بحمده والملائكة من خيفته» عند سماع الرعد، لورود ذلك عن النبي ﷺ بألفاظ مختلفة."], "k": "«حتى يغيّروا ما بأنفسهم»… نعمة أخاف زوالها؛ فهل أحرسها بالطاعة أم أعرّضها بالمعصية؟"}, {"lbl": "الآيات ١٤ – ١٦", "q": "لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَجِيبُونَ لَهُم بِشَيۡءٍ إِلَّا كَبَٰسِطِ كَفَّيۡهِ إِلَى ٱلۡمَآءِ لِيَبۡلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦۚ وَمَا دُعَآءُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ﴿١٤﴾ وَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩ ﴿١٥﴾ قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعٗا وَلَا ضَرّٗاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِي ٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ ٱلۡخَلۡقُ عَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّـٰرُ ﴿١٦﴾", "w": [["له دعوة الحق", "لله تعالى الدعوة الحق، فهو الإله الحق الذي لا إله إلا هو."], ["ليبلغ فاه", "ليبلغ الماء فمه."], ["إلا في ضلال", "في ضياع لا حصول منه على طائل."], ["بالغدو والآصال", "بالبُكَر جمع بُكرة، والعشايا جمع عشية."]], "m": "ما زال السياق في تقرير التوحيد بالأدلة: لله الدعوة الحق، فهو الإله الحق الذي لا إله إلا هو، أما غيره من الأصنام والأوثان وكل ما عُبد من دون الله فإطلاق لفظ إله عليه باطل، والدعوة إلى عبادته باطلة. والذين يدعونهم من دون الله لا يستجيبون لهم بشيء مما يطلبون منهم، إلا كاستجابة الماء لمن بسط كفيه إليه ليبلغ فاه وما هو ببالغه، فلا يصل إلى فمه وهو عطشان، فكذلك من يدعو غير الله لا يحصل منه على شيء، وما دعاء الكافرين إلا في ضياع وخسران. ولله يسجد من في السماوات من الملائكة، ومن في الأرض من المؤمنين طوعاً، والكافرون والمنافقون إذا أُكرهوا يسجدون كرهاً، وظلالهم تسجد في البكر والعشايا، وكلهم منقادون لقضاء الله وحكمه لا يستطيعون الخروج عنه. قل: من رب السماوات والأرض؟ قل: الله، إذ لا جواب لهم إلا هو، أفاتخذتم من دونه أولياء لا يملكون لأنفسهم نفعاً ولا ضراً؟ هل يستوي الأعمى والبصير، أم تستوي الظلمات والنور؟ فكيف يستوي المؤمن يعبد الله على بصيرة، والمشرك يعبد ما لا يسمع نداءً ولا يجيب دعاءً؟ أم جعلوا لله شركاء خلقوا كخلقه فتشابه الخلق عليهم؟ لا، فإنها لم تخلق شيئاً، قل: الله خالق كل شيء، وهو الواحد القهار المستحق للعبادة.", "h": ["دعوة الحق لله وحده، فهو المعبود بحق، لا إله غيره ولا رب سواه.", "خيبة المشركين في دعائهم وسائر عباداتهم.", "الخلق كلهم يسجدون لله طوعاً أو كرهاً، إذ الكل خاضع لحكم الله وتدبيره فيه.", "مشروعية السجود للقارئ والمستمع إذا بلغ هذه الآية: «وظلالهم بالغدو والآصال»، ويستحب أن يكون طاهراً مستقبلاً القبلة، ويكبّر عند الخفض والرفع ولا يسلّم.", "بطلان الشرك، إذ لا دليل عليه من عقل ولا نقل.", "وجوب العبادة لله تعالى."], "k": "«كباسط كفيه إلى الماء ليبلغ فاه»… لمن أمدّ يدي حين أحتاج: لمخلوق عاجز، أم للحي القيوم؟"}, {"lbl": "الآيتان ١٧ – ١٨", "q": "أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ ﴿١٧﴾ لِلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ أُوْلَـٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ﴿١٨﴾", "w": [["فسالت أودية بقدرها", "بمقدار مائها الذي يجري فيها."], ["زبداً رابياً", "غثاءً عالياً، إذ الزبد وضر غليان الماء أو جريانه."], ["ومما يوقدون عليه في النار", "كالذهب والفضة والنحاس."], ["ابتغاء حلية أو متاع", "طلباً لحلية من ذهب أو فضة، أو متاع من الأواني."], ["فيذهب جفاءً", "باطلاً مرمياً به بعيداً، إذ هو غثاء لا خير فيه."], ["فيمكث في الأرض", "يبقى في الأرض زمناً ينتفع به الناس."], ["للذين استجابوا لربهم الحسنى", "للذين آمنوا وعملوا الصالحات الجنة."], ["سوء الحساب", "المؤاخذة بكل ذنب عملوه، لا يُغفر لهم منه شيء."], ["وبئس المهاد", "الفراش الذي أعدّوه لأنفسهم، وهو جهنم."]], "m": "ضرب الله مثلاً للحق في بقائه، وللباطل في اضمحلاله: أنزل من السماء ماءً فسالت أودية بقدرها، بحسب كبرها وصغرها، فحمل السيل زبداً عالياً على سطح الماء، هذا مثل مائي. ومثل ناري: ومما يوقد عليه الصاغة والحدادون طلباً للحلية أو للمتاع كالأواني، يعلو ما كان فاسداً على صورة الزبد، ويبقى الصالح في البوتقة. كذلك يضرب الله الحق والباطل: فأما الزبد فيذهب باطلاً مرمياً به، يرميه السيل إلى ساحل الوادي ويرميه الصائغ عن بوتقته، وأما ما ينفع الناس من الماء والحلي والمتاع فيمكث ويبقى، كذلك يبيّن الله الأمثال ليعلموا فيؤمنوا ويهتدوا، فالحق باقٍ والباطل ذاهب وإن علا وطغا في بعض الأوقات. ثم أخبر بوعده ووعيده: للذين استجابوا لربهم بالإيمان والطاعة الحسنى، الجنة، والذين لم يستجيبوا لو أن لهم ما في الأرض جميعاً ومثله معه لافتدوا به من العذاب، أولئك لهم سوء الحساب، يحاسبون على كل صغيرة وكبيرة ولا يُغفر لهم منها شيء، ومأواهم جهنم وبئس الفراش.", "h": ["استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان.", "ثبات الحق، واضمحلال الباطل سنة من سنن الله تعالى.", "بيان وعد الله للمستجيبين له بالإيمان والطاعة، وهو الجنة.", "بيان وعيد الله لمن لم يستجب له بالإيمان والطاعة."], "k": "«فأما الزبد فيذهب جفاءً»… الباطل يعلو ثم يذهب؛ فهل أثبت على الحق وإن بدا الباطل غالباً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (164, 13, 19, 29, 'سورة الرعد ١٩ – ٢٩', 'صفات أولي الألباب وجزاؤهم، وصفات أهل الشقاء، و«ألا بذكر الله تطمئن القلوب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 164) = $j$[{"lbl": "الآيات ١٩ – ٢٤", "q": "۞أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿١٩﴾ ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ ﴿٢٠﴾ وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ ﴿٢١﴾ وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَـٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ ﴿٢٢﴾ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۖ وَٱلۡمَلَـٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ ﴿٢٣﴾ سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ ﴿٢٤﴾", "w": [["كمن هو أعمى", "لا يرى الحق ولا يعلمه ولا يؤمن به."], ["أولو الألباب", "أصحاب العقول."], ["يصلون ما أمر الله به أن يوصل", "من الإيمان والتوحيد والأرحام."], ["ويدرؤون بالحسنة السيئة", "يدفعون بالحلم الجهل، وبالصبر الأذى."], ["عقبى الدار", "العاقبة المحمودة في الدار الآخرة."], ["جنات عدن", "جنات إقامة دائمة."]], "m": "تضمّنت هذه الآيات مقارنة بين شخصيتين: مؤمن صالح كحمزة بن عبد المطلب، وكافر فاسد كأبي جهل، مع ذكر صفاتهما وجزائهما. أفمن يعلم أنما أُنزل إليك من ربك الحق فيؤمن به ويستقيم على منهجه، كمن هو أعمى لم يعلم الحق ولم يعمل به؟ لا يستويان، إنما يتعظ بمثل هذه المقارنة أصحاب العقول. ثم ذكر لهم ثماني صفات: الوفاء بعهد الله وعدم نقض الميثاق، إذ لا دين لمن لا عهد له، ووصل ما أمر الله به أن يوصل من الإيمان والإسلام والأرحام، وخشية الله المقتضية لطاعته، والخوف من سوء الحساب المقتضي لمحاسبة النفس، والصبر ابتغاء وجه ربهم على الطاعات وعن المعاصي وعلى البلاء، وإقامة الصلاة في أوقاتها بشروطها وأركانها، والإنفاق مما رزقهم الله سراً وعلانية، ودفع السيئة بالحسنة: سيئة الجهل بالحلم، وسيئة الأذى بالصبر. أولئك لهم العاقبة المحمودة: جنات إقامة يدخلونها ومن صلح من آبائهم وأزواجهم وذرياتهم، والملائكة يدخلون عليهم من كل باب تهنئهم بسلامة الوصول قائلين: سلام عليكم بما صبرتم، فنعم عقبى الدار.", "h": ["المؤمن حيّ يبصر ويعلم ويعمل، والكافر ميت أعمى لا يعلم ولا يعمل.", "الاتعاظ بالمواعظ يحصل لذي عقل راجح سليم.", "فضل هذه الصفات الثمانية المذكورة في هذه الآيات، أولها الوفاء بعهد الله، وآخرها درء السيئة بالحسنة.", "تفسير عقبى الدار، وأنها الجنة.", "بيان أن الملائكة تهنّئ أهل الجنة عند دخولهم وتسلّم عليهم."], "k": "«ويدرؤون بالحسنة السيئة»… إساءة وصلتني اليوم؛ بماذا أدفعها: بمثلها أم بحلم وصبر؟"}, {"lbl": "الآيات ٢٥ – ٢٩", "q": "وَٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِ أُوْلَـٰٓئِكَ لَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ ﴿٢٥﴾ ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ ﴿٢٦﴾ وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَنۡ أَنَابَ ﴿٢٧﴾ ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ ﴿٢٨﴾ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابٖ ﴿٢٩﴾", "w": [["والذين ينقضون عهد الله", "يحلّونه ولا يلتزمون به، فلم يعبدوا الله وحده."], ["ويقطعون ما أمر الله به أن يوصل", "من الإيمان والأرحام."], ["ويفسدون في الأرض", "بترك الصلاة ومنع الزكاة، وارتكاب السيئات وترك الحسنات."], ["لهم اللعنة", "البعد من رحمة الله تعالى."], ["ولهم سوء الدار", "جهنم وبئس المهاد."], ["ويقدر", "يضيّق ويقتّر."], ["إلا متاع", "قدر يسير يُتمتّع به زمناً ثم ينقضي."], ["طوبى لهم وحسن مآب", "لهم طوبى، شجرة في الجنة، وحسن منقلب وهو الجنة."]], "m": "هذا الطرف المقابل: من لم يعلم ولم يؤمن كأبي جهل، ذكر تعالى صفاته الموجبة لعذابه: نقض عهد الله من بعد ميثاقه، وقطع ما أمر الله به أن يوصل، والإفساد في الأرض بالشرك والمعاصي، أولئك لهم البعد من الرحمة ولهم سوء الدار. الله يبسط الرزق لمن يشاء امتحاناً هل يشكر، ويضيّق على من يشاء ابتلاءً هل يصبر، وقد لا يصلح بعضهم إلا الغنى، وبعضهم إلا الفقر، فلا الغنى دالّ على رضا الله، ولا الفقر دالّ على سخطه. وفرح الكافرون بالحياة الدنيا لجهلهم بمقدارها وعاقبتها، وما الحياة الدنيا بالنسبة إلى ما أعد الله لأوليائه إلا متاع قليل ككفّ التمر يُعطاه الراعي طول النهار ثم ينفد. ويقول الكافرون: لولا أُنزل عليه آية، قل: إن الله يضل من يشاء إضلاله ولو رأى ألوف الآيات، ويهدي إليه من أناب ولو لم ير آية. الذين آمنوا وتطمئن قلوبهم، أي تسكن وتستأنس بذكر الله وذكر وعده، ألا بذكر الله تطمئن قلوب المؤمنين، أما قلوب الكافرين فتطمئن لذكر الدنيا وملاذّها. الذين آمنوا وعملوا الصالحات طوبى لهم، حال من الحسن الطيب يعجز البيان عن وصفها، أو شجرة في الجنة، وحسن مرجع وهو الجنة.", "h": ["حرمة الاتصاف بصفات أهل الشقاء، وهي نقض العهد، وقطع ما أمر الله به أن يوصل، والإفساد في الأرض بالشرك والمعاصي.", "بيان أن الغنى والفقر يتمّان حسب علم الله تعالى امتحاناً وابتلاءً، فلا يدلّان على رضا الله ولا على سخطه.", "حقارة الدنيا وضآلة ما فيها من المتاع.", "فضل ذكر الله وسكون القلب إليه.", "وعد الله تعالى لأهل الإيمان والعمل الصالح بطوبى وحسن المآب."], "k": "«ألا بذكر الله تطمئن القلوب»… حين يضطرب قلبي، إلى أي ذكر أفزع: إلى هاتفي أم إلى ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 164;
insert into public.tdb_cards(topic, i, body) select 164, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٩ – ٢٤", "q": "۞أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿١٩﴾ ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ ﴿٢٠﴾ وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ ﴿٢١﴾ وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَـٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ ﴿٢٢﴾ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۖ وَٱلۡمَلَـٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ ﴿٢٣﴾ سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ ﴿٢٤﴾", "w": [["كمن هو أعمى", "لا يرى الحق ولا يعلمه ولا يؤمن به."], ["أولو الألباب", "أصحاب العقول."], ["يصلون ما أمر الله به أن يوصل", "من الإيمان والتوحيد والأرحام."], ["ويدرؤون بالحسنة السيئة", "يدفعون بالحلم الجهل، وبالصبر الأذى."], ["عقبى الدار", "العاقبة المحمودة في الدار الآخرة."], ["جنات عدن", "جنات إقامة دائمة."]], "m": "تضمّنت هذه الآيات مقارنة بين شخصيتين: مؤمن صالح كحمزة بن عبد المطلب، وكافر فاسد كأبي جهل، مع ذكر صفاتهما وجزائهما. أفمن يعلم أنما أُنزل إليك من ربك الحق فيؤمن به ويستقيم على منهجه، كمن هو أعمى لم يعلم الحق ولم يعمل به؟ لا يستويان، إنما يتعظ بمثل هذه المقارنة أصحاب العقول. ثم ذكر لهم ثماني صفات: الوفاء بعهد الله وعدم نقض الميثاق، إذ لا دين لمن لا عهد له، ووصل ما أمر الله به أن يوصل من الإيمان والإسلام والأرحام، وخشية الله المقتضية لطاعته، والخوف من سوء الحساب المقتضي لمحاسبة النفس، والصبر ابتغاء وجه ربهم على الطاعات وعن المعاصي وعلى البلاء، وإقامة الصلاة في أوقاتها بشروطها وأركانها، والإنفاق مما رزقهم الله سراً وعلانية، ودفع السيئة بالحسنة: سيئة الجهل بالحلم، وسيئة الأذى بالصبر. أولئك لهم العاقبة المحمودة: جنات إقامة يدخلونها ومن صلح من آبائهم وأزواجهم وذرياتهم، والملائكة يدخلون عليهم من كل باب تهنئهم بسلامة الوصول قائلين: سلام عليكم بما صبرتم، فنعم عقبى الدار.", "h": ["المؤمن حيّ يبصر ويعلم ويعمل، والكافر ميت أعمى لا يعلم ولا يعمل.", "الاتعاظ بالمواعظ يحصل لذي عقل راجح سليم.", "فضل هذه الصفات الثمانية المذكورة في هذه الآيات، أولها الوفاء بعهد الله، وآخرها درء السيئة بالحسنة.", "تفسير عقبى الدار، وأنها الجنة.", "بيان أن الملائكة تهنّئ أهل الجنة عند دخولهم وتسلّم عليهم."], "k": "«ويدرؤون بالحسنة السيئة»… إساءة وصلتني اليوم؛ بماذا أدفعها: بمثلها أم بحلم وصبر؟"}, {"lbl": "الآيات ٢٥ – ٢٩", "q": "وَٱلَّذِينَ يَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِيثَٰقِهِۦ وَيَقۡطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفۡسِدُونَ فِي ٱلۡأَرۡضِ أُوْلَـٰٓئِكَ لَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ ﴿٢٥﴾ ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ ﴿٢٦﴾ وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَةٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَنۡ أَنَابَ ﴿٢٧﴾ ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ ﴿٢٨﴾ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابٖ ﴿٢٩﴾", "w": [["والذين ينقضون عهد الله", "يحلّونه ولا يلتزمون به، فلم يعبدوا الله وحده."], ["ويقطعون ما أمر الله به أن يوصل", "من الإيمان والأرحام."], ["ويفسدون في الأرض", "بترك الصلاة ومنع الزكاة، وارتكاب السيئات وترك الحسنات."], ["لهم اللعنة", "البعد من رحمة الله تعالى."], ["ولهم سوء الدار", "جهنم وبئس المهاد."], ["ويقدر", "يضيّق ويقتّر."], ["إلا متاع", "قدر يسير يُتمتّع به زمناً ثم ينقضي."], ["طوبى لهم وحسن مآب", "لهم طوبى، شجرة في الجنة، وحسن منقلب وهو الجنة."]], "m": "هذا الطرف المقابل: من لم يعلم ولم يؤمن كأبي جهل، ذكر تعالى صفاته الموجبة لعذابه: نقض عهد الله من بعد ميثاقه، وقطع ما أمر الله به أن يوصل، والإفساد في الأرض بالشرك والمعاصي، أولئك لهم البعد من الرحمة ولهم سوء الدار. الله يبسط الرزق لمن يشاء امتحاناً هل يشكر، ويضيّق على من يشاء ابتلاءً هل يصبر، وقد لا يصلح بعضهم إلا الغنى، وبعضهم إلا الفقر، فلا الغنى دالّ على رضا الله، ولا الفقر دالّ على سخطه. وفرح الكافرون بالحياة الدنيا لجهلهم بمقدارها وعاقبتها، وما الحياة الدنيا بالنسبة إلى ما أعد الله لأوليائه إلا متاع قليل ككفّ التمر يُعطاه الراعي طول النهار ثم ينفد. ويقول الكافرون: لولا أُنزل عليه آية، قل: إن الله يضل من يشاء إضلاله ولو رأى ألوف الآيات، ويهدي إليه من أناب ولو لم ير آية. الذين آمنوا وتطمئن قلوبهم، أي تسكن وتستأنس بذكر الله وذكر وعده، ألا بذكر الله تطمئن قلوب المؤمنين، أما قلوب الكافرين فتطمئن لذكر الدنيا وملاذّها. الذين آمنوا وعملوا الصالحات طوبى لهم، حال من الحسن الطيب يعجز البيان عن وصفها، أو شجرة في الجنة، وحسن مرجع وهو الجنة.", "h": ["حرمة الاتصاف بصفات أهل الشقاء، وهي نقض العهد، وقطع ما أمر الله به أن يوصل، والإفساد في الأرض بالشرك والمعاصي.", "بيان أن الغنى والفقر يتمّان حسب علم الله تعالى امتحاناً وابتلاءً، فلا يدلّان على رضا الله ولا على سخطه.", "حقارة الدنيا وضآلة ما فيها من المتاع.", "فضل ذكر الله وسكون القلب إليه.", "وعد الله تعالى لأهل الإيمان والعمل الصالح بطوبى وحسن المآب."], "k": "«ألا بذكر الله تطمئن القلوب»… حين يضطرب قلبي، إلى أي ذكر أفزع: إلى هاتفي أم إلى ربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (165, 13, 30, 43, 'سورة الرعد ٣٠ – ٤٣', '«أفلم ييأس الذين آمنوا»، «يمحو الله ما يشاء ويثبت»، و«قل كفى بالله شهيداً بيني وبينكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 165) = $j$[{"lbl": "الآيات ٣٠ – ٣٢", "q": "كَذَٰلِكَ أَرۡسَلۡنَٰكَ فِيٓ أُمَّةٖ قَدۡ خَلَتۡ مِن قَبۡلِهَآ أُمَمٞ لِّتَتۡلُوَاْ عَلَيۡهِمُ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ قُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ ﴿٣٠﴾ وَلَوۡ أَنَّ قُرۡءَانٗا سُيِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِيعًاۗ أَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ أَن لَّوۡ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعٗاۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ تُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ أَوۡ تَحُلُّ قَرِيبٗا مِّن دَارِهِمۡ حَتَّىٰ يَأۡتِيَ وَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ ﴿٣١﴾ وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ ﴿٣٢﴾", "w": [["كذلك أرسلناك", "مثل ذلك الإرسال الذي أرسلنا به رسلنا أرسلناك."], ["لتتلو عليهم", "لتقرأ عليهم القرآن تذكيراً وتعليماً ونذارة وبشارة."], ["وهم يكفرون بالرحمن", "إذ قالوا: وما الرحمن؟ لا رحمن إلا رحمان اليمامة."], ["سُيّرت به الجبال", "نُقلت من أماكنها."], ["أو قُطّعت به الأرض", "شُقّقت فجُعلت أنهاراً وعيوناً."], ["أو كُلّم به الموتى", "أُحيوا وتكلّموا."], ["أفلم ييأس", "أفلم يعلم."], ["قارعة", "داهية تقرع قلوبهم بالخوف والحزن وتهلكهم وتستأصلهم."], ["أو تحل قريباً من دارهم", "أي القارعة، أو الجيش الإسلامي."], ["فأمليت", "أمهلت وأخّرت مدة طويلة."]], "m": "ما زال السياق في تقرير أصول العقيدة: كذلك الإرسال الذي أرسلنا به من قبلك أرسلناك في أمة قد خلت من قبلها أمم، لتتلو عليهم الذي أوحينا إليك، وهو الرحمة والهدى والشفاء، وهم يكفرون بالرحمن الذي أرسلك لهم، قل: هو ربي لا إله إلا هو، عليه توكلت وإليه توبتي ورجوعي. وكان مشركو مكة قد طالبوا أن تُسيّر عنهم جبال مكة لتتسع أرضهم للزراعة، وأن تُقطّع أرضهم فتخرج منها العيون، وأن يُحيا لهم موتاهم فيسألوهم عن صدقه، فقال تعالى: ولو أن قرآناً سُيّرت به الجبال أو قُطّعت به الأرض أو كُلّم به الموتى لكان هذا القرآن، ولكن ليست الآيات هي التي تهدي، بل لله الأمر جميعاً، يهدي من يشاء ويضل من يشاء، ولما علم أنهم لو أُعطوها لما آمنوا فيحقّ عليهم عذاب الإبادة صرفهم عنها. وكان من المؤمنين من يودّ الآيات ظناً أن المشركين يؤمنون لو شاهدوها، فقال: أفلم يعلم الذين آمنوا أن لو يشاء الله لهدى الناس جميعاً بلا آيات؟ ولا يزال الذين كفروا تصيبهم بما صنعوا من الشرك والمعاصي داهية تقرع قلوبهم كالجدب والمرض والقتل والأسر، أو يحلّ الرسول بجيشه قريباً من دارهم حتى يأتي وعد الله بفتح مكة، إن الله لا يخلف الميعاد. ولقد استُهزئ برسل من قبلك فصبروا فاصبر، فأمهلت الذين كفروا حتى قامت الحجة عليهم ثم أخذتهم، فكيف كان عقابي؟ كان شديداً عاماً.", "h": ["تقرير التوحيد.", "لا توكّل إلا على الله، ولا توبة لأحد إلا إليه.", "عظمة القرآن الكريم وبيان فضله.", "إطلاق لفظ اليأس، والمراد به العلم.", "توعّد الرب تعالى الكافرين بالقوارع في الدنيا إلى يوم القيامة.", "الله جل جلاله يملي ويمهل، ولكن لا يهمل، بل يؤاخذ ويعاقب."], "k": "«عليه توكلت وإليه متاب»… كلمتان تجمعان الطريق: توكّل في أمري، ورجوع إليه من ذنبي."}, {"lbl": "الآيات ٣٣ – ٣٥", "q": "أَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُواْ لِلَّهِ شُرَكَآءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعۡلَمُ فِي ٱلۡأَرۡضِ أَم بِظَٰهِرٖ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُيِّنَ لِلَّذِينَ كَفَرُواْ مَكۡرُهُمۡ وَصُدُّواْ عَنِ ٱلسَّبِيلِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ ﴿٣٣﴾ لَّهُمۡ عَذَابٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ ﴿٣٤﴾ ۞مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ أُكُلُهَا دَآئِمٞ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِينَ ٱتَّقَواْۚ وَّعُقۡبَى ٱلۡكَٰفِرِينَ ٱلنَّارُ ﴿٣٥﴾", "w": [["أفمن هو قائم على كل نفس بما كسبت", "حافظها ورازقها وعالم بها وبما كسبت، ومجازيها بعملها."], ["أم تنبّئونه بما لا يعلم", "أتخبرونه بما لا يعلمه؟"], ["بظاهر من القول", "بظن باطل لا حقيقة له في الواقع."], ["واق", "مانع يمنعهم من العذاب."], ["مثل الجنة", "صفتها التي نقصّها عليك."], ["أكلها دائم وظلها", "ما يؤكل فيها دائم لا يفنى، وظلها دائم لا يزول."]], "m": "ما زال السياق في تقرير التوحيد وإبطال الشرك: أفمن هو قائم على كل نفس، حافظها ورازقها وعالم بما كسبت من خير وشر ومجازيها، كمن لا يحفظ ولا يرزق ولا يعلم ولا يجزي، وهي الأصنام؟ فبطل تأليهها. وجعلوا لله شركاء يعبدونهم معه، قل: سمّوهم، صفوهم، بيّنوا من هم؟ أتنبّئون الله بما لا يعلم في الأرض، أم بظن باطل لا حقيقة له؟ بل زُيّن للذين كفروا مكرهم، قولهم الكاذب وافتراؤهم، فصُدّوا عن سبيل الحق، ومن يضلل الله فما له من هاد. لهم عذاب في الحياة الدنيا بالقتل والأسر، ولعذاب الآخرة أشق، وما لهم من الله من واق يصرفه عنهم. ولما ذكر عذاب أهل الكفر ذكر نعيم أهل الإيمان والتقوى: صفة الجنة التي وُعد المتقون تجري من تحتها الأنهار، طعامها دائم لا ينفد، وظلها دائم لا يزول ولا تنسخه شمس كظل الدنيا، تلك عاقبة الذين اتقوا ربهم فآمنوا به ووحّدوه وأطاعوه، وعاقبة الكافرين النار.", "h": ["تقرير التوحيد، إذ الأصنام لا تحفظ ولا ترزق ولا تحاسب ولا تجزي، والله هو القائم على كل نفس، فهو الإله الحق، وما عداه فآلهة باطلة لا حقيقة لها إلا مجرد أسماء.", "استمرار الكفار على كفرهم هو نتيجة تزيين الشيطان لهم ذلك، فصدّهم عن السبيل.", "ميزة القرآن الكريم في الجمع بين الوعد والوعيد، إذ بهما تمكن هداية الناس."], "k": "«أفمن هو قائم على كل نفس بما كسبت»… ربي قائم عليّ الآن، يرى ما أكسب؛ فماذا أكسب في هذه الساعة؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ بِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ ﴿٣٦﴾ وَكَذَٰلِكَ أَنزَلۡنَٰهُ حُكۡمًا عَرَبِيّٗاۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا وَاقٖ ﴿٣٧﴾ وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَٰجٗا وَذُرِّيَّةٗۚ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلٖ كِتَابٞ ﴿٣٨﴾ يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ ﴿٣٩﴾", "w": [["والذين آتيناهم الكتاب", "كعبد الله بن سلام ومن آمن من اليهود."], ["يفرحون بما أُنزل إليك", "يُسرّون به لأنهم مؤمنون صادقون، ولأنه موافق لما عندهم."], ["ومن الأحزاب", "من اليهود والمشركين."], ["من ينكر بعضه", "بعض القرآن، فالمشركون أنكروا لفظ الرحمن."], ["وكذلك أنزلناه حكماً عربياً", "بلسان العرب لتحكم به بينهم."], ["لكل أجل كتاب", "لكل مدة كتاب كُتبت فيه المدة المحددة."], ["يمحو الله ما يشاء", "يمحو من الأحكام وغيرها ويثبت ما يشاء، فما محاه هو المنسوخ، وما أبقاه هو المحكم."]], "m": "ما زال السياق في تقرير أصول العقيدة: والذين آتيناهم الكتاب، كعبد الله بن سلام، يفرحون بما أُنزل إليك، وفي هذا تقرير للوحي، ومن الأحزاب من ينكر بعضه: فاليهود أنكروا أغلب ما فيه من الأحكام ولم يصدّقوا إلا بالقصص، والمشركون أنكروا «الرحمن». قل: إنما أُمرت أن أعبد الله ولا أشرك به، إليه أدعو وإليه رجوعي. وكهذا الإنزال أنزلناه بلسان العرب لتحكم به بينهم، ولئن اتبعت أهواءهم بعد ما جاءك من العلم، وحاشاه ﷺ، وإنما هو من باب: إياكِ أعني واسمعي يا جارة، ما لك من الله من ولي ينصرك ولا واقٍ يقيك. ولقد أرسلنا رسلاً من قبلك، من نوح وإبراهيم إلى موسى وداود وسليمان، وجعلنا لهم أزواجاً وذرية، فلا معنى لمن عابه بالزواج. وما كان لرسول أن يأتي بآية إلا بإذن الله، فالرسل مربوبون لا يملكون مع الله شيئاً، لكل وقت محدّد كتاب كُتب فيه ذلك الأجل فلا فوضى. يمحو الله ما يشاء ويثبت، ردّاً على قولهم: لِمَ يُثبت الشيء ثم يبطله؟ كاستقبال بيت المقدس ثم الكعبة، فهو تعالى يمحو من الشرائع والأحكام ما يشاء بحسب حاجة عباده، ويثبت ما هو صالح لهم، وعنده أم الكتاب الذي حوى كل المقادير فلا يدخله تبديل ولا تغيير، كالموت والحياة والسعادة والشقاء.", "h": ["تقرير عقيدة الوحي والنبوة.", "تقرير عقيدة التوحيد.", "تقرير أن القضاء والحكم في الإسلام مصدره الأول القرآن الكريم، ثم السنة لبيانها للقرآن، ثم القياس المأذون فيه، فإجماع الأمة لاستحالة اجتماعها على غير ما يحب الله تعالى ويرضى به.", "التحذير من اتباع أصحاب البدع والأهواء والملل والنحل الباطلة.", "تقرير عقيدة القضاء والقدر.", "بيان النسخ في الأحكام بالكتاب والسنة."], "k": "«ولئن اتبعت أهواءهم بعد ما جاءك من العلم»… هل أترك ما أعلمه من الحق مجاملةً لأهواء من حولي؟"}, {"lbl": "الآيات ٤٠ – ٤٣", "q": "وَإِن مَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ ﴿٤٠﴾ أَوَلَمۡ يَرَوۡاْ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ يَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِيعُ ٱلۡحِسَابِ ﴿٤١﴾ وَقَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِيعٗاۖ يَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسٖۗ وَسَيَعۡلَمُ ٱلۡكُفَّـٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ ﴿٤٢﴾ وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَسۡتَ مُرۡسَلٗاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ ﴿٤٣﴾", "w": [["نعدهم", "من العذاب."], ["أو نتوفّينّك", "قبل ذلك."], ["ننقصها من أطرافها", "بلداً بعد بلد بالفتح ودخول الإسلام فيها وانتهاء الشرك منها."], ["لا معقّب لحكمه", "لا رادّ له، بحيث لا يتعقّب حكمه فيبطله."], ["ومن عنده علم الكتاب", "من مؤمني اليهود والنصارى."]], "m": "وإما نُرينّك بعض الذي نعد قومك من العذاب فذاك، وإن توفّيناك قبل ذلك فليس عليك إلا البلاغ وقد بلّغت، وعلينا الحساب، فلا تأسَ ولا تضق ذرعاً بما يمكرون. أوَلم ير المشركون المطالبون بالآيات أنا نأتي الأرض ننقصها من أطرافها، نفتحها للإسلام بلداً بعد بلد؟ أليس ذلك آية على صدق الرسول ﷺ؟ والله يحكم في خلقه بما يشاء، فيعزّ ويذلّ، ويعطي ويمنع، ولا معقّب لحكمه يبطله، وهو سريع الحساب. وقد مكر الذين من قبلهم فكان عاقبة مكرهم دمارهم أجمعين، فلله المكر جميعاً، فلا عبرة بمكرهم ولا يُلتفت إليه، يعلم ما تكسب كل نفس، فأين مكر من لا يعلم من مكر من يعلم كل شيء؟ وسيعلم الكفار يوم القيامة لمن العاقبة الحميدة. ويقول الذين كفروا: لست مرسلاً، قل: كفى بالله شهيداً بيني وبينكم، وقد شهد لي بالرسالة وأقسم عليها مرات في كلامه، وكفى بشهادة مؤمني أهل الكتاب الذين عندهم علم التوراة والإنجيل، كعبد الله بن سلام وسلمان الفارسي والنجاشي وتميم الداري.", "h": ["انتصار الإسلام وانتشاره في ظرف ربع قرن أكبر دليل على أنه حق.", "أحكام الله تعالى لا تُرد، ولا يجوز طلب الاستئناف على حكم من أحكام الله تعالى في كتابه أو في سنة رسوله ﷺ.", "شهادة الله أعظم شهادة، فلا تُطلب بعدها شهادة إذا كان الخصام بين مؤمنين.", "فضل العالم على الجاهل، إذ شهادة مؤمني أهل الكتاب تقوم بها الحجة على من لا علم لهم من المشركين."], "k": "«فإنما عليك البلاغ وعلينا الحساب»… أؤدّي ما عليّ وأترك النتائج لربي؛ فلماذا يثقلني ما ليس بيدي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 165;
insert into public.tdb_cards(topic, i, body) select 165, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٠ – ٣٢", "q": "كَذَٰلِكَ أَرۡسَلۡنَٰكَ فِيٓ أُمَّةٖ قَدۡ خَلَتۡ مِن قَبۡلِهَآ أُمَمٞ لِّتَتۡلُوَاْ عَلَيۡهِمُ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ قُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ ﴿٣٠﴾ وَلَوۡ أَنَّ قُرۡءَانٗا سُيِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِيعًاۗ أَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ أَن لَّوۡ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعٗاۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ تُصِيبُهُم بِمَا صَنَعُواْ قَارِعَةٌ أَوۡ تَحُلُّ قَرِيبٗا مِّن دَارِهِمۡ حَتَّىٰ يَأۡتِيَ وَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ ﴿٣١﴾ وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ ﴿٣٢﴾", "w": [["كذلك أرسلناك", "مثل ذلك الإرسال الذي أرسلنا به رسلنا أرسلناك."], ["لتتلو عليهم", "لتقرأ عليهم القرآن تذكيراً وتعليماً ونذارة وبشارة."], ["وهم يكفرون بالرحمن", "إذ قالوا: وما الرحمن؟ لا رحمن إلا رحمان اليمامة."], ["سُيّرت به الجبال", "نُقلت من أماكنها."], ["أو قُطّعت به الأرض", "شُقّقت فجُعلت أنهاراً وعيوناً."], ["أو كُلّم به الموتى", "أُحيوا وتكلّموا."], ["أفلم ييأس", "أفلم يعلم."], ["قارعة", "داهية تقرع قلوبهم بالخوف والحزن وتهلكهم وتستأصلهم."], ["أو تحل قريباً من دارهم", "أي القارعة، أو الجيش الإسلامي."], ["فأمليت", "أمهلت وأخّرت مدة طويلة."]], "m": "ما زال السياق في تقرير أصول العقيدة: كذلك الإرسال الذي أرسلنا به من قبلك أرسلناك في أمة قد خلت من قبلها أمم، لتتلو عليهم الذي أوحينا إليك، وهو الرحمة والهدى والشفاء، وهم يكفرون بالرحمن الذي أرسلك لهم، قل: هو ربي لا إله إلا هو، عليه توكلت وإليه توبتي ورجوعي. وكان مشركو مكة قد طالبوا أن تُسيّر عنهم جبال مكة لتتسع أرضهم للزراعة، وأن تُقطّع أرضهم فتخرج منها العيون، وأن يُحيا لهم موتاهم فيسألوهم عن صدقه، فقال تعالى: ولو أن قرآناً سُيّرت به الجبال أو قُطّعت به الأرض أو كُلّم به الموتى لكان هذا القرآن، ولكن ليست الآيات هي التي تهدي، بل لله الأمر جميعاً، يهدي من يشاء ويضل من يشاء، ولما علم أنهم لو أُعطوها لما آمنوا فيحقّ عليهم عذاب الإبادة صرفهم عنها. وكان من المؤمنين من يودّ الآيات ظناً أن المشركين يؤمنون لو شاهدوها، فقال: أفلم يعلم الذين آمنوا أن لو يشاء الله لهدى الناس جميعاً بلا آيات؟ ولا يزال الذين كفروا تصيبهم بما صنعوا من الشرك والمعاصي داهية تقرع قلوبهم كالجدب والمرض والقتل والأسر، أو يحلّ الرسول بجيشه قريباً من دارهم حتى يأتي وعد الله بفتح مكة، إن الله لا يخلف الميعاد. ولقد استُهزئ برسل من قبلك فصبروا فاصبر، فأمهلت الذين كفروا حتى قامت الحجة عليهم ثم أخذتهم، فكيف كان عقابي؟ كان شديداً عاماً.", "h": ["تقرير التوحيد.", "لا توكّل إلا على الله، ولا توبة لأحد إلا إليه.", "عظمة القرآن الكريم وبيان فضله.", "إطلاق لفظ اليأس، والمراد به العلم.", "توعّد الرب تعالى الكافرين بالقوارع في الدنيا إلى يوم القيامة.", "الله جل جلاله يملي ويمهل، ولكن لا يهمل، بل يؤاخذ ويعاقب."], "k": "«عليه توكلت وإليه متاب»… كلمتان تجمعان الطريق: توكّل في أمري، ورجوع إليه من ذنبي."}, {"lbl": "الآيات ٣٣ – ٣٥", "q": "أَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُواْ لِلَّهِ شُرَكَآءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعۡلَمُ فِي ٱلۡأَرۡضِ أَم بِظَٰهِرٖ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُيِّنَ لِلَّذِينَ كَفَرُواْ مَكۡرُهُمۡ وَصُدُّواْ عَنِ ٱلسَّبِيلِۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ ﴿٣٣﴾ لَّهُمۡ عَذَابٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ ﴿٣٤﴾ ۞مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ أُكُلُهَا دَآئِمٞ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِينَ ٱتَّقَواْۚ وَّعُقۡبَى ٱلۡكَٰفِرِينَ ٱلنَّارُ ﴿٣٥﴾", "w": [["أفمن هو قائم على كل نفس بما كسبت", "حافظها ورازقها وعالم بها وبما كسبت، ومجازيها بعملها."], ["أم تنبّئونه بما لا يعلم", "أتخبرونه بما لا يعلمه؟"], ["بظاهر من القول", "بظن باطل لا حقيقة له في الواقع."], ["واق", "مانع يمنعهم من العذاب."], ["مثل الجنة", "صفتها التي نقصّها عليك."], ["أكلها دائم وظلها", "ما يؤكل فيها دائم لا يفنى، وظلها دائم لا يزول."]], "m": "ما زال السياق في تقرير التوحيد وإبطال الشرك: أفمن هو قائم على كل نفس، حافظها ورازقها وعالم بما كسبت من خير وشر ومجازيها، كمن لا يحفظ ولا يرزق ولا يعلم ولا يجزي، وهي الأصنام؟ فبطل تأليهها. وجعلوا لله شركاء يعبدونهم معه، قل: سمّوهم، صفوهم، بيّنوا من هم؟ أتنبّئون الله بما لا يعلم في الأرض، أم بظن باطل لا حقيقة له؟ بل زُيّن للذين كفروا مكرهم، قولهم الكاذب وافتراؤهم، فصُدّوا عن سبيل الحق، ومن يضلل الله فما له من هاد. لهم عذاب في الحياة الدنيا بالقتل والأسر، ولعذاب الآخرة أشق، وما لهم من الله من واق يصرفه عنهم. ولما ذكر عذاب أهل الكفر ذكر نعيم أهل الإيمان والتقوى: صفة الجنة التي وُعد المتقون تجري من تحتها الأنهار، طعامها دائم لا ينفد، وظلها دائم لا يزول ولا تنسخه شمس كظل الدنيا، تلك عاقبة الذين اتقوا ربهم فآمنوا به ووحّدوه وأطاعوه، وعاقبة الكافرين النار.", "h": ["تقرير التوحيد، إذ الأصنام لا تحفظ ولا ترزق ولا تحاسب ولا تجزي، والله هو القائم على كل نفس، فهو الإله الحق، وما عداه فآلهة باطلة لا حقيقة لها إلا مجرد أسماء.", "استمرار الكفار على كفرهم هو نتيجة تزيين الشيطان لهم ذلك، فصدّهم عن السبيل.", "ميزة القرآن الكريم في الجمع بين الوعد والوعيد، إذ بهما تمكن هداية الناس."], "k": "«أفمن هو قائم على كل نفس بما كسبت»… ربي قائم عليّ الآن، يرى ما أكسب؛ فماذا أكسب في هذه الساعة؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَفۡرَحُونَ بِمَآ أُنزِلَ إِلَيۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن يُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَآ أُشۡرِكَ بِهِۦٓۚ إِلَيۡهِ أَدۡعُواْ وَإِلَيۡهِ مَـَٔابِ ﴿٣٦﴾ وَكَذَٰلِكَ أَنزَلۡنَٰهُ حُكۡمًا عَرَبِيّٗاۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا وَاقٖ ﴿٣٧﴾ وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَٰجٗا وَذُرِّيَّةٗۚ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلٖ كِتَابٞ ﴿٣٨﴾ يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ ﴿٣٩﴾", "w": [["والذين آتيناهم الكتاب", "كعبد الله بن سلام ومن آمن من اليهود."], ["يفرحون بما أُنزل إليك", "يُسرّون به لأنهم مؤمنون صادقون، ولأنه موافق لما عندهم."], ["ومن الأحزاب", "من اليهود والمشركين."], ["من ينكر بعضه", "بعض القرآن، فالمشركون أنكروا لفظ الرحمن."], ["وكذلك أنزلناه حكماً عربياً", "بلسان العرب لتحكم به بينهم."], ["لكل أجل كتاب", "لكل مدة كتاب كُتبت فيه المدة المحددة."], ["يمحو الله ما يشاء", "يمحو من الأحكام وغيرها ويثبت ما يشاء، فما محاه هو المنسوخ، وما أبقاه هو المحكم."]], "m": "ما زال السياق في تقرير أصول العقيدة: والذين آتيناهم الكتاب، كعبد الله بن سلام، يفرحون بما أُنزل إليك، وفي هذا تقرير للوحي، ومن الأحزاب من ينكر بعضه: فاليهود أنكروا أغلب ما فيه من الأحكام ولم يصدّقوا إلا بالقصص، والمشركون أنكروا «الرحمن». قل: إنما أُمرت أن أعبد الله ولا أشرك به، إليه أدعو وإليه رجوعي. وكهذا الإنزال أنزلناه بلسان العرب لتحكم به بينهم، ولئن اتبعت أهواءهم بعد ما جاءك من العلم، وحاشاه ﷺ، وإنما هو من باب: إياكِ أعني واسمعي يا جارة، ما لك من الله من ولي ينصرك ولا واقٍ يقيك. ولقد أرسلنا رسلاً من قبلك، من نوح وإبراهيم إلى موسى وداود وسليمان، وجعلنا لهم أزواجاً وذرية، فلا معنى لمن عابه بالزواج. وما كان لرسول أن يأتي بآية إلا بإذن الله، فالرسل مربوبون لا يملكون مع الله شيئاً، لكل وقت محدّد كتاب كُتب فيه ذلك الأجل فلا فوضى. يمحو الله ما يشاء ويثبت، ردّاً على قولهم: لِمَ يُثبت الشيء ثم يبطله؟ كاستقبال بيت المقدس ثم الكعبة، فهو تعالى يمحو من الشرائع والأحكام ما يشاء بحسب حاجة عباده، ويثبت ما هو صالح لهم، وعنده أم الكتاب الذي حوى كل المقادير فلا يدخله تبديل ولا تغيير، كالموت والحياة والسعادة والشقاء.", "h": ["تقرير عقيدة الوحي والنبوة.", "تقرير عقيدة التوحيد.", "تقرير أن القضاء والحكم في الإسلام مصدره الأول القرآن الكريم، ثم السنة لبيانها للقرآن، ثم القياس المأذون فيه، فإجماع الأمة لاستحالة اجتماعها على غير ما يحب الله تعالى ويرضى به.", "التحذير من اتباع أصحاب البدع والأهواء والملل والنحل الباطلة.", "تقرير عقيدة القضاء والقدر.", "بيان النسخ في الأحكام بالكتاب والسنة."], "k": "«ولئن اتبعت أهواءهم بعد ما جاءك من العلم»… هل أترك ما أعلمه من الحق مجاملةً لأهواء من حولي؟"}, {"lbl": "الآيات ٤٠ – ٤٣", "q": "وَإِن مَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ ﴿٤٠﴾ أَوَلَمۡ يَرَوۡاْ أَنَّا نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ يَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِيعُ ٱلۡحِسَابِ ﴿٤١﴾ وَقَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِيعٗاۖ يَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسٖۗ وَسَيَعۡلَمُ ٱلۡكُفَّـٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ ﴿٤٢﴾ وَيَقُولُ ٱلَّذِينَ كَفَرُواْ لَسۡتَ مُرۡسَلٗاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَٰبِ ﴿٤٣﴾", "w": [["نعدهم", "من العذاب."], ["أو نتوفّينّك", "قبل ذلك."], ["ننقصها من أطرافها", "بلداً بعد بلد بالفتح ودخول الإسلام فيها وانتهاء الشرك منها."], ["لا معقّب لحكمه", "لا رادّ له، بحيث لا يتعقّب حكمه فيبطله."], ["ومن عنده علم الكتاب", "من مؤمني اليهود والنصارى."]], "m": "وإما نُرينّك بعض الذي نعد قومك من العذاب فذاك، وإن توفّيناك قبل ذلك فليس عليك إلا البلاغ وقد بلّغت، وعلينا الحساب، فلا تأسَ ولا تضق ذرعاً بما يمكرون. أوَلم ير المشركون المطالبون بالآيات أنا نأتي الأرض ننقصها من أطرافها، نفتحها للإسلام بلداً بعد بلد؟ أليس ذلك آية على صدق الرسول ﷺ؟ والله يحكم في خلقه بما يشاء، فيعزّ ويذلّ، ويعطي ويمنع، ولا معقّب لحكمه يبطله، وهو سريع الحساب. وقد مكر الذين من قبلهم فكان عاقبة مكرهم دمارهم أجمعين، فلله المكر جميعاً، فلا عبرة بمكرهم ولا يُلتفت إليه، يعلم ما تكسب كل نفس، فأين مكر من لا يعلم من مكر من يعلم كل شيء؟ وسيعلم الكفار يوم القيامة لمن العاقبة الحميدة. ويقول الذين كفروا: لست مرسلاً، قل: كفى بالله شهيداً بيني وبينكم، وقد شهد لي بالرسالة وأقسم عليها مرات في كلامه، وكفى بشهادة مؤمني أهل الكتاب الذين عندهم علم التوراة والإنجيل، كعبد الله بن سلام وسلمان الفارسي والنجاشي وتميم الداري.", "h": ["انتصار الإسلام وانتشاره في ظرف ربع قرن أكبر دليل على أنه حق.", "أحكام الله تعالى لا تُرد، ولا يجوز طلب الاستئناف على حكم من أحكام الله تعالى في كتابه أو في سنة رسوله ﷺ.", "شهادة الله أعظم شهادة، فلا تُطلب بعدها شهادة إذا كان الخصام بين مؤمنين.", "فضل العالم على الجاهل، إذ شهادة مؤمني أهل الكتاب تقوم بها الحجة على من لا علم لهم من المشركين."], "k": "«فإنما عليك البلاغ وعلينا الحساب»… أؤدّي ما عليّ وأترك النتائج لربي؛ فلماذا يثقلني ما ليس بيدي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (166, 14, 1, 14, 'سورة إبراهيم ١ – ١٤', '«لتخرج الناس من الظلمات إلى النور»، «لئن شكرتم لأزيدنّكم»، و«أفي الله شك»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 166) = $j$[{"lbl": "الآيات ١ – ٥", "q": "الٓرۚ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ﴿١﴾ ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَوَيۡلٞ لِّلۡكَٰفِرِينَ مِنۡ عَذَابٖ شَدِيدٍ ﴿٢﴾ ٱلَّذِينَ يَسۡتَحِبُّونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجًاۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلِۭ بَعِيدٖ ﴿٣﴾ وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٤﴾ وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ﴿٥﴾", "w": [["الر", "من الحروف المقطعة، تُكتب «الر» وتُقرأ: ألف، لام، را، والتفويض فيها أسلم: الله أعلم بمراده بذلك."], ["كتاب", "هذا كتاب عظيم."], ["من الظلمات", "من ظلمات الكفر إلى نور الإيمان."], ["عن سبيل الله", "الإسلام."], ["بآياتنا", "المعجزات التسع: العصا، واليد، والطوفان، والجراد، والقمّل، والضفادع، والدم، والطمس، والسنين ونقص الثمرات."], ["بأيام الله", "ببلائه ونعمائه."]], "m": "هذا كتاب عظيم القدر أنزلناه إليك يا رسولنا لتخرج الناس من ظلمات الكفر والجهل إلى نور الإيمان والعلم الشرعي، بتوفيق ربهم ومعونته، إلى طريق العزيز الغالب الحميد المحمود بآلائه وإفضاله، الله الذي له ما في السماوات وما في الأرض خلقاً وملكاً وتدبيراً. والكافرون معرضون عنه، فويل لهم من عذاب شديد: الذين يفضّلون الحياة الدنيا فيعملون لها ويتركون العمل للآخرة، ويصدّون أنفسهم وغيرهم عن الإسلام، ويريدونه معوجّاً يوافق أهواءهم حتى يرضوه ديناً، أولئك في ضلال بعيد لا يكاد صاحبه يرجع منه. وما أرسلنا من رسول إلا بلغة قومه ليبيّن لهم، ثم يضل الله من يشاء ويهدي من يشاء، وهو العزيز الحكيم، فلا يضل إلا من رغب في الضلال وآثره وحارب المهتدين، وليس من حكمته أن يضل من يطلب الهدى ويسعى إليه. ولقد أرسلنا موسى بآياتنا: أن أخرج قومك من ظلمات الشرك إلى نور التوحيد، وذكّرهم بأيام الله: بلائه ونعمه، إذ أنجاهم من آل فرعون وأنعم عليهم بالمنّ والسلوى، ليحملهم ذلك على الشكر، إن في ذلك لآيات لكل كثير الصبر كثير الشكر.", "h": ["إقامة الحجة على المكذّبين بالقرآن الكريم، إذ هو مؤلّف من الحروف المقطعة مثل: الر، وطسم، والم، وحم، ولم يستطيعوا أن يأتوا بمثله، بل بسورة مثله.", "بيان أن الكفر ظلام، والإيمان نور.", "الحكمة في إرسال الله تعالى الرسل بلغات أقوامهم.", "تقرير أن الذي يخلق الهداية هو الله، وأما العبد فليس له أكثر من الكسب.", "فضيلة التذكير بالخير والشر ليُشكر الله ويُتّقى.", "فضيلة الصبر والشكر."], "k": "«إن في ذلك لآيات لكل صبار شكور»… صبر على ما أصابني، وشكر على ما أُعطيت؛ أيهما ينقصني اليوم؟"}, {"lbl": "الآيات ٦ – ٩", "q": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ ﴿٦﴾ وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ ﴿٧﴾ وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ ﴿٨﴾ أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡ لَا يَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا بِمَآ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِي شَكّٖ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبٖ ﴿٩﴾", "w": [["يسومونكم", "يذيقونكم."], ["ويستحيون نساءكم", "يستبقونهن."], ["بلاء من ربكم عظيم", "ابتلاء واختبار، ويكون بالخير والشر."], ["وإذ تأذّن ربكم", "أعلم ربكم."], ["بالبينات", "بالحجج الواضحة على صدقهم في دعوة النبوة والتوحيد والبعث الآخر."], ["فردّوا أيديهم في أفواههم", "أشاروا إليهم أن اسكتوا."], ["مريب", "موقع في الريبة."]], "m": "اذكر يا رسولنا إذ قال موسى لقومه: اذكروا نعمة الله عليكم لتشكروها بتوحيده وطاعته، فإن من ذكر شكر، إذ أنجاكم من آل فرعون يذيقونكم أسوأ العذاب، ويذبحون المواليد الذكور، لأن الكهنة قالوا لفرعون: لا يبعد أن يسقط عرشك على يد رجل من بني إسرائيل، ويستبقون الإناث للخدمة، وفي ذلك ابتلاء من ربكم عظيم: بلاء بالشر في العذاب، وبلاء بالخير في النجاة منه. وإذ أعلم ربكم مقسماً: لئن شكرتم نعمي بعبادتي وتوحيدي وطاعتي وطاعة رسولي لأزيدنّكم في الإنعام، ولئن كفرتم نعمي فعصيتموني لأسلبنّها منكم وأعذّبكم، إن عذابي لشديد. وقال موسى: إن تكفروا أنتم ومن في الأرض جميعاً فإن الله لغني عن خلقه، حميد محمود بنعمه. ألم يأتكم نبأ الذين من قبلكم: قوم نوح وعاد وثمود والذين من بعدهم لا يعلم عددهم إلا الله؟ جاءتهم رسلهم بالحجج على صدق دعوتهم، فردّوا أيديهم إلى أفواههم تغيّظاً، أو أشاروا إليهم بالسكوت، وقالوا: إنا كفرنا بما أُرسلتم به، وإنا لفي شك مما تدعوننا إليه موقع في القلق والاضطراب.", "h": ["مشروعية التذكير بنعم الله لنشكر ولا نكفر.", "وعد الله تعالى بالمزيد من النعم لمن شكر نعم الله عليه.", "كفر النعم سبب زوالها.", "بيان غنى الله تعالى المطلق عن سائر خلقه، فالناس إن شكروا شكروا لأنفسهم، وإن كفروا كفروا على أنفسهم.", "التذكير بقصص السابقين وأحوال الغابرين مشروع، وفيه فوائد عظيمة."], "k": "«لئن شكرتم لأزيدنّكم»… نعمة واحدة أشكر الله عليها الآن بلساني وعملي؛ ما هي؟"}, {"lbl": "الآيات ١٠ – ١٤", "q": "۞قَالَتۡ رُسُلُهُمۡ أَفِي ٱللَّهِ شَكّٞ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَدۡعُوكُمۡ لِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۚ قَالُوٓاْ إِنۡ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتُونَا بِسُلۡطَٰنٖ مُّبِينٖ ﴿١٠﴾ قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرٞ مِّثۡلُكُمۡ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَآ أَن نَّأۡتِيَكُم بِسُلۡطَٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١١﴾ وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ﴿١٢﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّـٰلِمِينَ ﴿١٣﴾ وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ ﴿١٤﴾", "w": [["أفي الله شك", "لا شك في وجود الله ولا في توحيده، إذ الاستفهام للإنكار."], ["إلى أجل مسمى", "إلى أجل الموت."], ["بسلطان مبين", "بحجة ظاهرة تدل على صدقكم."], ["يمنّ على من يشاء", "بالنبوة والرسالة على من يشاء لذلك."], ["وقد هدانا سبلنا", "طرقه التي عرفناه بها، وعرفنا عظيم قدرته وعز سلطانه."], ["لنخرجنّكم من أرضنا", "من ديارنا، أو لتعودنّ في ديننا."], ["لمن خاف مقامي", "وقوفه بين يديّ يوم القيامة للحساب والجزاء."]], "m": "قالت الرسل لأممهم الكافرة: أفي الله شك وهو فاطر السماوات والأرض؟ فخالقهما وحده لا يُعقل أن يكون له شريك في عبادته، يدعوكم إلى الإيمان والعمل الصالح ليغفر لكم من ذنوبكم، أما مظالم الناس فردّوها إليهم، ويؤخّر العذاب عنكم لتموتوا بآجالكم. قالوا: ما أنتم إلا بشر مثلنا، تريدون أن تصرفونا عما كان يعبد آباؤنا، فأتونا بحجة ظاهرة على صدقكم. قالت لهم رسلهم: ما نحن إلا بشر مثلكم، ولكن الله يمنّ على من يشاء بالنبوة، فمنّ علينا بها، وما كان لنا أن نأتيكم بسلطان إلا بإذن الله، وعليه فليتوكل المؤمنون. وما لنا ألا نتوكل على الله وقد هدانا طرقنا التي عرفناه بها، ولنصبرنّ على ما آذيتمونا بألسنتكم وأيديكم حتى ينتقم الله لنا. وقال الذين كفروا لرسلهم مهدّدين: لنخرجنّكم من أرضنا أو لتعودنّ في ملتنا، فأوحى إليهم ربهم: لنهلكنّ الظالمين، ولم يقل: لنهلكنّهم، إشارة إلى علة الهلاك وهي الظلم، ولنسكننّكم الأرض من بعدهم، ذلك الإنجاء للمؤمنين والإهلاك للظالمين لمن خاف الوقوف بين يديّ يوم القيامة وخاف وعيدي.", "h": ["بطلان الشك في وجود الله وعلمه وقدرته وحكمته، ووجوب عبادته وحده، وذلك لكثرة الأدلة وقوة الحجج وسطوع البراهين.", "بيان ما كان أهل الكفر يقابلون به رسل الله والدعاة إليه سبحانه.", "وجوب التوكل على الله تعالى، وعدم صحة التوكل على غيره، إذ لا كافي إلا الله.", "وجوب الصبر على الأذى في سبيل الله، وانتظار الفرج بأخذ الظالمين.", "عاقبة الظلم، وهي الخسران والدمار، لا تتبدّل ولا تتخلّف وإن طال الزمن."], "k": "«وما لنا ألا نتوكل على الله وقد هدانا سبلنا»… من هداني إليه، ألا يكفيني فيما أخاف؟"}]$j$::jsonb then 0 else 1 end;
