insert into public.tdb_cards(topic, i, body) select 166, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "الٓرۚ كِتَٰبٌ أَنزَلۡنَٰهُ إِلَيۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَٰطِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ ﴿١﴾ ٱللَّهِ ٱلَّذِي لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَوَيۡلٞ لِّلۡكَٰفِرِينَ مِنۡ عَذَابٖ شَدِيدٍ ﴿٢﴾ ٱلَّذِينَ يَسۡتَحِبُّونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجًاۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلِۭ بَعِيدٖ ﴿٣﴾ وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٤﴾ وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ ﴿٥﴾", "w": [["الر", "من الحروف المقطعة، تُكتب «الر» وتُقرأ: ألف، لام، را، والتفويض فيها أسلم: الله أعلم بمراده بذلك."], ["كتاب", "هذا كتاب عظيم."], ["من الظلمات", "من ظلمات الكفر إلى نور الإيمان."], ["عن سبيل الله", "الإسلام."], ["بآياتنا", "المعجزات التسع: العصا، واليد، والطوفان، والجراد، والقمّل، والضفادع، والدم، والطمس، والسنين ونقص الثمرات."], ["بأيام الله", "ببلائه ونعمائه."]], "m": "هذا كتاب عظيم القدر أنزلناه إليك يا رسولنا لتخرج الناس من ظلمات الكفر والجهل إلى نور الإيمان والعلم الشرعي، بتوفيق ربهم ومعونته، إلى طريق العزيز الغالب الحميد المحمود بآلائه وإفضاله، الله الذي له ما في السماوات وما في الأرض خلقاً وملكاً وتدبيراً. والكافرون معرضون عنه، فويل لهم من عذاب شديد: الذين يفضّلون الحياة الدنيا فيعملون لها ويتركون العمل للآخرة، ويصدّون أنفسهم وغيرهم عن الإسلام، ويريدونه معوجّاً يوافق أهواءهم حتى يرضوه ديناً، أولئك في ضلال بعيد لا يكاد صاحبه يرجع منه. وما أرسلنا من رسول إلا بلغة قومه ليبيّن لهم، ثم يضل الله من يشاء ويهدي من يشاء، وهو العزيز الحكيم، فلا يضل إلا من رغب في الضلال وآثره وحارب المهتدين، وليس من حكمته أن يضل من يطلب الهدى ويسعى إليه. ولقد أرسلنا موسى بآياتنا: أن أخرج قومك من ظلمات الشرك إلى نور التوحيد، وذكّرهم بأيام الله: بلائه ونعمه، إذ أنجاهم من آل فرعون وأنعم عليهم بالمنّ والسلوى، ليحملهم ذلك على الشكر، إن في ذلك لآيات لكل كثير الصبر كثير الشكر.", "h": ["إقامة الحجة على المكذّبين بالقرآن الكريم، إذ هو مؤلّف من الحروف المقطعة مثل: الر، وطسم، والم، وحم، ولم يستطيعوا أن يأتوا بمثله، بل بسورة مثله.", "بيان أن الكفر ظلام، والإيمان نور.", "الحكمة في إرسال الله تعالى الرسل بلغات أقوامهم.", "تقرير أن الذي يخلق الهداية هو الله، وأما العبد فليس له أكثر من الكسب.", "فضيلة التذكير بالخير والشر ليُشكر الله ويُتّقى.", "فضيلة الصبر والشكر."], "k": "«إن في ذلك لآيات لكل صبار شكور»… صبر على ما أصابني، وشكر على ما أُعطيت؛ أيهما ينقصني اليوم؟"}, {"lbl": "الآيات ٦ – ٩", "q": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ سُوٓءَ ٱلۡعَذَابِ وَيُذَبِّحُونَ أَبۡنَآءَكُمۡ وَيَسۡتَحۡيُونَ نِسَآءَكُمۡۚ وَفِي ذَٰلِكُم بَلَآءٞ مِّن رَّبِّكُمۡ عَظِيمٞ ﴿٦﴾ وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ ﴿٧﴾ وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ ﴿٨﴾ أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡ لَا يَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرَدُّوٓاْ أَيۡدِيَهُمۡ فِيٓ أَفۡوَٰهِهِمۡ وَقَالُوٓاْ إِنَّا كَفَرۡنَا بِمَآ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِي شَكّٖ مِّمَّا تَدۡعُونَنَآ إِلَيۡهِ مُرِيبٖ ﴿٩﴾", "w": [["يسومونكم", "يذيقونكم."], ["ويستحيون نساءكم", "يستبقونهن."], ["بلاء من ربكم عظيم", "ابتلاء واختبار، ويكون بالخير والشر."], ["وإذ تأذّن ربكم", "أعلم ربكم."], ["بالبينات", "بالحجج الواضحة على صدقهم في دعوة النبوة والتوحيد والبعث الآخر."], ["فردّوا أيديهم في أفواههم", "أشاروا إليهم أن اسكتوا."], ["مريب", "موقع في الريبة."]], "m": "اذكر يا رسولنا إذ قال موسى لقومه: اذكروا نعمة الله عليكم لتشكروها بتوحيده وطاعته، فإن من ذكر شكر، إذ أنجاكم من آل فرعون يذيقونكم أسوأ العذاب، ويذبحون المواليد الذكور، لأن الكهنة قالوا لفرعون: لا يبعد أن يسقط عرشك على يد رجل من بني إسرائيل، ويستبقون الإناث للخدمة، وفي ذلك ابتلاء من ربكم عظيم: بلاء بالشر في العذاب، وبلاء بالخير في النجاة منه. وإذ أعلم ربكم مقسماً: لئن شكرتم نعمي بعبادتي وتوحيدي وطاعتي وطاعة رسولي لأزيدنّكم في الإنعام، ولئن كفرتم نعمي فعصيتموني لأسلبنّها منكم وأعذّبكم، إن عذابي لشديد. وقال موسى: إن تكفروا أنتم ومن في الأرض جميعاً فإن الله لغني عن خلقه، حميد محمود بنعمه. ألم يأتكم نبأ الذين من قبلكم: قوم نوح وعاد وثمود والذين من بعدهم لا يعلم عددهم إلا الله؟ جاءتهم رسلهم بالحجج على صدق دعوتهم، فردّوا أيديهم إلى أفواههم تغيّظاً، أو أشاروا إليهم بالسكوت، وقالوا: إنا كفرنا بما أُرسلتم به، وإنا لفي شك مما تدعوننا إليه موقع في القلق والاضطراب.", "h": ["مشروعية التذكير بنعم الله لنشكر ولا نكفر.", "وعد الله تعالى بالمزيد من النعم لمن شكر نعم الله عليه.", "كفر النعم سبب زوالها.", "بيان غنى الله تعالى المطلق عن سائر خلقه، فالناس إن شكروا شكروا لأنفسهم، وإن كفروا كفروا على أنفسهم.", "التذكير بقصص السابقين وأحوال الغابرين مشروع، وفيه فوائد عظيمة."], "k": "«لئن شكرتم لأزيدنّكم»… نعمة واحدة أشكر الله عليها الآن بلساني وعملي؛ ما هي؟"}, {"lbl": "الآيات ١٠ – ١٤", "q": "۞قَالَتۡ رُسُلُهُمۡ أَفِي ٱللَّهِ شَكّٞ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ يَدۡعُوكُمۡ لِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۚ قَالُوٓاْ إِنۡ أَنتُمۡ إِلَّا بَشَرٞ مِّثۡلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتُونَا بِسُلۡطَٰنٖ مُّبِينٖ ﴿١٠﴾ قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرٞ مِّثۡلُكُمۡ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَآ أَن نَّأۡتِيَكُم بِسُلۡطَٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ﴿١١﴾ وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ﴿١٢﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۖ فَأَوۡحَىٰٓ إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّـٰلِمِينَ ﴿١٣﴾ وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَٰلِكَ لِمَنۡ خَافَ مَقَامِي وَخَافَ وَعِيدِ ﴿١٤﴾", "w": [["أفي الله شك", "لا شك في وجود الله ولا في توحيده، إذ الاستفهام للإنكار."], ["إلى أجل مسمى", "إلى أجل الموت."], ["بسلطان مبين", "بحجة ظاهرة تدل على صدقكم."], ["يمنّ على من يشاء", "بالنبوة والرسالة على من يشاء لذلك."], ["وقد هدانا سبلنا", "طرقه التي عرفناه بها، وعرفنا عظيم قدرته وعز سلطانه."], ["لنخرجنّكم من أرضنا", "من ديارنا، أو لتعودنّ في ديننا."], ["لمن خاف مقامي", "وقوفه بين يديّ يوم القيامة للحساب والجزاء."]], "m": "قالت الرسل لأممهم الكافرة: أفي الله شك وهو فاطر السماوات والأرض؟ فخالقهما وحده لا يُعقل أن يكون له شريك في عبادته، يدعوكم إلى الإيمان والعمل الصالح ليغفر لكم من ذنوبكم، أما مظالم الناس فردّوها إليهم، ويؤخّر العذاب عنكم لتموتوا بآجالكم. قالوا: ما أنتم إلا بشر مثلنا، تريدون أن تصرفونا عما كان يعبد آباؤنا، فأتونا بحجة ظاهرة على صدقكم. قالت لهم رسلهم: ما نحن إلا بشر مثلكم، ولكن الله يمنّ على من يشاء بالنبوة، فمنّ علينا بها، وما كان لنا أن نأتيكم بسلطان إلا بإذن الله، وعليه فليتوكل المؤمنون. وما لنا ألا نتوكل على الله وقد هدانا طرقنا التي عرفناه بها، ولنصبرنّ على ما آذيتمونا بألسنتكم وأيديكم حتى ينتقم الله لنا. وقال الذين كفروا لرسلهم مهدّدين: لنخرجنّكم من أرضنا أو لتعودنّ في ملتنا، فأوحى إليهم ربهم: لنهلكنّ الظالمين، ولم يقل: لنهلكنّهم، إشارة إلى علة الهلاك وهي الظلم، ولنسكننّكم الأرض من بعدهم، ذلك الإنجاء للمؤمنين والإهلاك للظالمين لمن خاف الوقوف بين يديّ يوم القيامة وخاف وعيدي.", "h": ["بطلان الشك في وجود الله وعلمه وقدرته وحكمته، ووجوب عبادته وحده، وذلك لكثرة الأدلة وقوة الحجج وسطوع البراهين.", "بيان ما كان أهل الكفر يقابلون به رسل الله والدعاة إليه سبحانه.", "وجوب التوكل على الله تعالى، وعدم صحة التوكل على غيره، إذ لا كافي إلا الله.", "وجوب الصبر على الأذى في سبيل الله، وانتظار الفرج بأخذ الظالمين.", "عاقبة الظلم، وهي الخسران والدمار، لا تتبدّل ولا تتخلّف وإن طال الزمن."], "k": "«وما لنا ألا نتوكل على الله وقد هدانا سبلنا»… من هداني إليه، ألا يكفيني فيما أخاف؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (167, 14, 15, 30, 'سورة إبراهيم ١٥ – ٣٠', 'خطبة الشيطان في النار، ومثل الكلمة الطيبة والكلمة الخبيثة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 167) = $j$[{"lbl": "الآيات ١٥ – ٢٠", "q": "وَٱسۡتَفۡتَحُواْ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٖ ﴿١٥﴾ مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسۡقَىٰ مِن مَّآءٖ صَدِيدٖ ﴿١٦﴾ يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأۡتِيهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانٖ وَمَا هُوَ بِمَيِّتٖۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٞ ﴿١٧﴾ مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ لَّا يَقۡدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَيۡءٖۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ ﴿١٨﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ ﴿١٩﴾ وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ ﴿٢٠﴾", "w": [["واستفتحوا", "طلب الرسل الفتح لهم، أي النصر على أقوامهم."], ["وخاب", "خسر وهلك."], ["كل جبار عنيد", "ظالم يجبر الناس على مراده، كثير العناد."], ["من ماء صديد", "ما يخرج سائلاً من أجواف أهل النار مختلطاً من قيح ودم وعرق."], ["يتجرّعه ولا يكاد يسيغه", "يبتلعه مرة بعد مرة لمرارته، ولا يقارب ازدراده لقبحه ومرارته."], ["ويأتيه الموت من كل مكان", "لشدة ما يحيط به من العذاب، فكل أسباب الموت حاصلة ولكن لا يموت."], ["أعمالهم كرماد", "الصالحة منها كصلة الرحم وبر الوالدين وإقراء الضيف، والفاسدة كعبادة الأصنام."], ["لا يقدرون مما كسبوا على شيء", "لا يحصلون من أعمالهم على ثواب وإن قلّ، لأنها باطلة بالشرك."], ["وما ذلك على الله بعزيز", "بصعب ممتنع عليه."]], "m": "هذا آخر ما ذكّر به موسى قومه من أنباء الأمم السابقة: واستفتح الرسل، طلبوا من الله النصر على أعدائه، فاستجاب لهم، وخسر وهلك كل ظالم طاغٍ معاند للحق. من ورائه جهنم تنتظره، يعطش فيها ويطلب الماء فيُسقى من صديد أهل النار، يبتلعه جرعة بعد أخرى ولا يكاد يُدخله جوفه لقبحه ونتنه ومرارته، ويأتيه الموت من كل مكان، إذ العذاب محيط به من فوقه ومن تحته وعن يمينه وعن شماله، وما هو بميت، ومن ورائه عذاب غليظ لا يطاق. مثل أعمال الذين كفروا بربهم، الصالحة منها والطالحة، كرماد اشتدت به الريح في يوم شديد هبوب الريح، لا يحصلون مما كسبوا على شيء من الثواب، ذلك هو الضلال البعيد إذ ذهب عمله كله سدى. ألم تعلم أن الله خلق السماوات والأرض بالحق، من أجل الإنسان ليذكر الله ويشكره؟ فإذا تنكّر لربه فكفر به عذّبه، إن يشأ يذهبكم أيها المتمرّدون على طاعته، ويأت بخلق جديد يعبدونه ويوحّدونه، وما ذلك على الله بممتنع.", "h": ["إنجاز وعد الله لرسله في قوله: «فأوحى إليهم ربهم لنهلكنّ الظالمين».", "خيبة وخسران عامة أهل الشرك والكفر والظلم.", "عظم عذاب يوم القيامة وشدته.", "بطلان أعمال المشركين والكافرين، وخيبتهم فيها، إذ لا ينتفعون بشيء منها.", "عذاب أهل الكفر والشرك والظلم لازم، لأنهم لم يذكروا ولم يشكروا، والذكر والشكر علة الوجود كله، فلما عبثوا بالحياة استحقوا عذاباً أبدياً."], "k": "«مثل الذين كفروا بربهم أعمالهم كرماد»… عمل بلا إيمان وإخلاص يذهب هباءً؛ فلمن أعمل ما أعمله اليوم؟"}, {"lbl": "الآيات ٢١ – ٢٣", "q": "وَبَرَزُواْ لِلَّهِ جَمِيعٗا فَقَالَ ٱلضُّعَفَـٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ مِن شَيۡءٖۚ قَالُواْ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَيۡنَٰكُمۡۖ سَوَآءٌ عَلَيۡنَآ أَجَزِعۡنَآ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِيصٖ ﴿٢١﴾ وَقَالَ ٱلشَّيۡطَٰنُ لَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ فَلَا تَلُومُونِي وَلُومُوٓاْ أَنفُسَكُمۖ مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ إِنِّي كَفَرۡتُ بِمَآ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّـٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٢٢﴾ وَأُدۡخِلَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِيَّتُهُمۡ فِيهَا سَلَٰمٌ ﴿٢٣﴾", "w": [["وبرزوا لله جميعاً", "برزت الخلائق كلها لله، وذلك يوم القيامة."], ["إنا كنا لكم تبعاً", "تابعين لكم فيما تعتقدون وتعملون."], ["فهل أنتم مغنون عنا", "دافعون عنا بعض العذاب."], ["ما لنا من محيص", "من ملجأ ومهرب ومنجى."], ["لما قُضي الأمر", "بإدخال أهل الجنة الجنة، وأهل النار النار."], ["ما أنا بمصرخكم", "بمغيثكم مما أنتم فيه من العذاب والكرب."], ["تجري من تحتها الأنهار", "من تحت قصورها وأشجارها الأنهار الأربعة: الماء، واللبن، والخمر، والعسل."]], "m": "في هذه الآيات عرض سريع للموقف وما بعده: وخرجت البشرية من قبورها لله جميعاً، فقال الأتباع الضعفاء للرؤساء المستكبرين: إنا كنا لكم أتباعاً في عقائدكم، فهل تدفعون عنا شيئاً من عذاب الله؟ قالوا: لو هدانا الله لهديناكم، فاعترفوا الآن أن الهداية بيد الله، سواء علينا أجزعنا أم صبرنا، ما لنا من مهرب. وهنا يقوم إبليس خطيباً فيهم لما قُضي الأمر: إن الله وعدكم وعد الحق، بأن من آمن وعمل صالحاً أدخله جنته، ومن كفر أدخله النار، ووعدتكم أن وعد الله ووعيده ليس بحق، فأخلفتكم وكنت كاذباً مغرّراً بكم، وما كان لي عليكم من قوة أكرهتكم بها، إلا أن دعوتكم فاستجبتم لي، فلا تلوموني ولوموا أنفسكم، ما أنا بمغيثكم وما أنتم بمغيثيّ، إني كفرت بما أشركتموني من قبل، إذ كل عابد لغير الله في الواقع عابد للشيطان، إن الظالمين لهم عذاب أليم. وأُدخل الذين آمنوا وعملوا الصالحات جنات تجري من خلال قصورها وأشجارها الأنهار، خالدين فيها بإذن ربهم، تحيّتهم فيها سلام: يحيّيهم ربهم والملائكة ويحيّي بعضهم بعضاً.", "h": ["بيان أن التقليد والتبعية لا تكون عذراً لصاحبها عند الله تعالى.", "بيان أن الشيطان هو المعبود من دون الله تعالى، إذ هو الذي دعا إلى عبادة غير الله.", "تقرير لعلم الله بما لم يكن كيف يكون، إذ ما جاء في الآيات من حوار لم يكن بعد، ولكنه في علم الله كائن كما هو، وسوف يكون كما جاء لا يتخلّف منه حرف.", "وعيد الظالمين بأليم العذاب.", "العمل لا يُدخل الجنة إلا بوصفه سبباً لا غير، وإلا فدخول الجنة يكون بإذن الله تعالى."], "k": "«فلا تلوموني ولوموا أنفسكم»… يومها يتبرّأ الشيطان؛ فهل ألوم نفسي اليوم وأتوب قبل فوات الأوان؟"}, {"lbl": "الآيات ٢٤ – ٣٠", "q": "أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ ﴿٢٤﴾ تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٢٥﴾ وَمَثَلُ كَلِمَةٍ خَبِيثَةٖ كَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارٖ ﴿٢٦﴾ يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ ﴿٢٧﴾ ۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ ﴿٢٨﴾ جَهَنَّمَ يَصۡلَوۡنَهَاۖ وَبِئۡسَ ٱلۡقَرَارُ ﴿٢٩﴾ وَجَعَلُواْ لِلَّهِ أَندَادٗا لِّيُضِلُّواْ عَن سَبِيلِهِۦۗ قُلۡ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ ﴿٣٠﴾", "w": [["كلمة طيبة", "هي: لا إله إلا الله محمد رسول الله."], ["كشجرة طيبة", "هي النخلة."], ["كلمة خبيثة", "هي كلمة الكفر."], ["كشجرة خبيثة", "هي الحنظل."], ["اجتُثّت", "اقتُلعت جثتها، أي جسمها وذاتها."], ["بالقول الثابت", "هو: لا إله إلا الله."], ["وفي الآخرة", "في القبر، فيجيب الملكين عما يسألانه عنه، عن ربه ودينه ونبيه."], ["بدّلوا نعمة الله كفراً", "بدّلوا التوحيد والإسلام بالجحود والشرك."], ["دار البوار", "جهنم."], ["وجعلوا لله أنداداً", "شركاء."]], "m": "ألم تر أيها الرسول كيف ضرب الله مثلاً كلمة طيبة، كلمة الإيمان يقولها المؤمن، كشجرة طيبة هي النخلة، أصلها ثابت في الأرض وفرعها عالٍ في السماء، تعطي ثمرها كل حين: بلحاً وبُسراً ورطباً وتمراً، في الصباح والمساء، بإذن ربها، فكلمة «لا إله إلا الله محمد رسول الله» تثمر للعبد أعمالاً صالحة كل حين، وترفع إلى الله، ويضرب الله الأمثال للناس لعلهم يتذكرون فيؤمنوا. ومثل كلمة الكفر في قلب الكافر كشجرة خبيثة، الحنظل، اقتُلعت من فوق الأرض ما لها من ثبات، ولا تثمر إلا المرارة. يثبّت الله الذين آمنوا بالقول الثابت في الحياة الدنيا مهما كانت الفتن والمحن حتى يموتوا على الإيمان، وفي القبر عندما يسألهم الملكان: من ربك؟ ما دينك؟ من نبيك؟ ويضل الله الظالمين فلا يوفّقهم للقول الثابت لإصرارهم على الشرك وأذيتهم المؤمنين، ويفعل الله ما يشاء بحكم عالية. ألم تر إلى الذين بدّلوا نعمة الله، الإسلام، كفراً فكذّبوا الرسول، وأحلّوا قومهم دار الهلاك جهنم يصلونها وبئس القرار، وجعلوا لله شركاء كاللات والعزى ليَضِلوا ويُضِلّوا عن سبيله؟ قل: تمتّعوا بما أنتم فيه، فإن مصيركم إلى النار.", "h": ["استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان.", "المقارنة بين الإيمان والكفر، وكلمة التوحيد وكلمة الكفر، وما يثمره كل واحد منهما.", "بشرى المؤمن بتثبيت الله تعالى له على إيمانه حتى يموت مؤمناً، وبالنجاة من عذاب القبر حيث يجيب منكراً ونكيراً على سؤالهما إياه بتثبيت الله تعالى له.", "الأمر في قوله تعالى: «تمتعوا» ليس للإباحة ولا للوجوب، وإنما هو للتهديد والوعيد."], "k": "«تؤتي أكلها كل حين بإذن ربها»… شهادتي تثمر كل يوم؛ فما الثمرة التي أخرجتها اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 167;
insert into public.tdb_cards(topic, i, body) select 167, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٥ – ٢٠", "q": "وَٱسۡتَفۡتَحُواْ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٖ ﴿١٥﴾ مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسۡقَىٰ مِن مَّآءٖ صَدِيدٖ ﴿١٦﴾ يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأۡتِيهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانٖ وَمَا هُوَ بِمَيِّتٖۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٞ ﴿١٧﴾ مَّثَلُ ٱلَّذِينَ كَفَرُواْ بِرَبِّهِمۡۖ أَعۡمَٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ لَّا يَقۡدِرُونَ مِمَّا كَسَبُواْ عَلَىٰ شَيۡءٖۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ ﴿١٨﴾ أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَأۡتِ بِخَلۡقٖ جَدِيدٖ ﴿١٩﴾ وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ ﴿٢٠﴾", "w": [["واستفتحوا", "طلب الرسل الفتح لهم، أي النصر على أقوامهم."], ["وخاب", "خسر وهلك."], ["كل جبار عنيد", "ظالم يجبر الناس على مراده، كثير العناد."], ["من ماء صديد", "ما يخرج سائلاً من أجواف أهل النار مختلطاً من قيح ودم وعرق."], ["يتجرّعه ولا يكاد يسيغه", "يبتلعه مرة بعد مرة لمرارته، ولا يقارب ازدراده لقبحه ومرارته."], ["ويأتيه الموت من كل مكان", "لشدة ما يحيط به من العذاب، فكل أسباب الموت حاصلة ولكن لا يموت."], ["أعمالهم كرماد", "الصالحة منها كصلة الرحم وبر الوالدين وإقراء الضيف، والفاسدة كعبادة الأصنام."], ["لا يقدرون مما كسبوا على شيء", "لا يحصلون من أعمالهم على ثواب وإن قلّ، لأنها باطلة بالشرك."], ["وما ذلك على الله بعزيز", "بصعب ممتنع عليه."]], "m": "هذا آخر ما ذكّر به موسى قومه من أنباء الأمم السابقة: واستفتح الرسل، طلبوا من الله النصر على أعدائه، فاستجاب لهم، وخسر وهلك كل ظالم طاغٍ معاند للحق. من ورائه جهنم تنتظره، يعطش فيها ويطلب الماء فيُسقى من صديد أهل النار، يبتلعه جرعة بعد أخرى ولا يكاد يُدخله جوفه لقبحه ونتنه ومرارته، ويأتيه الموت من كل مكان، إذ العذاب محيط به من فوقه ومن تحته وعن يمينه وعن شماله، وما هو بميت، ومن ورائه عذاب غليظ لا يطاق. مثل أعمال الذين كفروا بربهم، الصالحة منها والطالحة، كرماد اشتدت به الريح في يوم شديد هبوب الريح، لا يحصلون مما كسبوا على شيء من الثواب، ذلك هو الضلال البعيد إذ ذهب عمله كله سدى. ألم تعلم أن الله خلق السماوات والأرض بالحق، من أجل الإنسان ليذكر الله ويشكره؟ فإذا تنكّر لربه فكفر به عذّبه، إن يشأ يذهبكم أيها المتمرّدون على طاعته، ويأت بخلق جديد يعبدونه ويوحّدونه، وما ذلك على الله بممتنع.", "h": ["إنجاز وعد الله لرسله في قوله: «فأوحى إليهم ربهم لنهلكنّ الظالمين».", "خيبة وخسران عامة أهل الشرك والكفر والظلم.", "عظم عذاب يوم القيامة وشدته.", "بطلان أعمال المشركين والكافرين، وخيبتهم فيها، إذ لا ينتفعون بشيء منها.", "عذاب أهل الكفر والشرك والظلم لازم، لأنهم لم يذكروا ولم يشكروا، والذكر والشكر علة الوجود كله، فلما عبثوا بالحياة استحقوا عذاباً أبدياً."], "k": "«مثل الذين كفروا بربهم أعمالهم كرماد»… عمل بلا إيمان وإخلاص يذهب هباءً؛ فلمن أعمل ما أعمله اليوم؟"}, {"lbl": "الآيات ٢١ – ٢٣", "q": "وَبَرَزُواْ لِلَّهِ جَمِيعٗا فَقَالَ ٱلضُّعَفَـٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ مِن شَيۡءٖۚ قَالُواْ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَيۡنَٰكُمۡۖ سَوَآءٌ عَلَيۡنَآ أَجَزِعۡنَآ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِيصٖ ﴿٢١﴾ وَقَالَ ٱلشَّيۡطَٰنُ لَمَّا قُضِيَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِيَ عَلَيۡكُم مِّن سُلۡطَٰنٍ إِلَّآ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِيۖ فَلَا تَلُومُونِي وَلُومُوٓاْ أَنفُسَكُمۖ مَّآ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَآ أَنتُم بِمُصۡرِخِيَّ إِنِّي كَفَرۡتُ بِمَآ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّـٰلِمِينَ لَهُمۡ عَذَابٌ أَلِيمٞ ﴿٢٢﴾ وَأُدۡخِلَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِيَّتُهُمۡ فِيهَا سَلَٰمٌ ﴿٢٣﴾", "w": [["وبرزوا لله جميعاً", "برزت الخلائق كلها لله، وذلك يوم القيامة."], ["إنا كنا لكم تبعاً", "تابعين لكم فيما تعتقدون وتعملون."], ["فهل أنتم مغنون عنا", "دافعون عنا بعض العذاب."], ["ما لنا من محيص", "من ملجأ ومهرب ومنجى."], ["لما قُضي الأمر", "بإدخال أهل الجنة الجنة، وأهل النار النار."], ["ما أنا بمصرخكم", "بمغيثكم مما أنتم فيه من العذاب والكرب."], ["تجري من تحتها الأنهار", "من تحت قصورها وأشجارها الأنهار الأربعة: الماء، واللبن، والخمر، والعسل."]], "m": "في هذه الآيات عرض سريع للموقف وما بعده: وخرجت البشرية من قبورها لله جميعاً، فقال الأتباع الضعفاء للرؤساء المستكبرين: إنا كنا لكم أتباعاً في عقائدكم، فهل تدفعون عنا شيئاً من عذاب الله؟ قالوا: لو هدانا الله لهديناكم، فاعترفوا الآن أن الهداية بيد الله، سواء علينا أجزعنا أم صبرنا، ما لنا من مهرب. وهنا يقوم إبليس خطيباً فيهم لما قُضي الأمر: إن الله وعدكم وعد الحق، بأن من آمن وعمل صالحاً أدخله جنته، ومن كفر أدخله النار، ووعدتكم أن وعد الله ووعيده ليس بحق، فأخلفتكم وكنت كاذباً مغرّراً بكم، وما كان لي عليكم من قوة أكرهتكم بها، إلا أن دعوتكم فاستجبتم لي، فلا تلوموني ولوموا أنفسكم، ما أنا بمغيثكم وما أنتم بمغيثيّ، إني كفرت بما أشركتموني من قبل، إذ كل عابد لغير الله في الواقع عابد للشيطان، إن الظالمين لهم عذاب أليم. وأُدخل الذين آمنوا وعملوا الصالحات جنات تجري من خلال قصورها وأشجارها الأنهار، خالدين فيها بإذن ربهم، تحيّتهم فيها سلام: يحيّيهم ربهم والملائكة ويحيّي بعضهم بعضاً.", "h": ["بيان أن التقليد والتبعية لا تكون عذراً لصاحبها عند الله تعالى.", "بيان أن الشيطان هو المعبود من دون الله تعالى، إذ هو الذي دعا إلى عبادة غير الله.", "تقرير لعلم الله بما لم يكن كيف يكون، إذ ما جاء في الآيات من حوار لم يكن بعد، ولكنه في علم الله كائن كما هو، وسوف يكون كما جاء لا يتخلّف منه حرف.", "وعيد الظالمين بأليم العذاب.", "العمل لا يُدخل الجنة إلا بوصفه سبباً لا غير، وإلا فدخول الجنة يكون بإذن الله تعالى."], "k": "«فلا تلوموني ولوموا أنفسكم»… يومها يتبرّأ الشيطان؛ فهل ألوم نفسي اليوم وأتوب قبل فوات الأوان؟"}, {"lbl": "الآيات ٢٤ – ٣٠", "q": "أَلَمۡ تَرَ كَيۡفَ ضَرَبَ ٱللَّهُ مَثَلٗا كَلِمَةٗ طَيِّبَةٗ كَشَجَرَةٖ طَيِّبَةٍ أَصۡلُهَا ثَابِتٞ وَفَرۡعُهَا فِي ٱلسَّمَآءِ ﴿٢٤﴾ تُؤۡتِيٓ أُكُلَهَا كُلَّ حِينِۭ بِإِذۡنِ رَبِّهَاۗ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٢٥﴾ وَمَثَلُ كَلِمَةٍ خَبِيثَةٖ كَشَجَرَةٍ خَبِيثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارٖ ﴿٢٦﴾ يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ ﴿٢٧﴾ ۞أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ ﴿٢٨﴾ جَهَنَّمَ يَصۡلَوۡنَهَاۖ وَبِئۡسَ ٱلۡقَرَارُ ﴿٢٩﴾ وَجَعَلُواْ لِلَّهِ أَندَادٗا لِّيُضِلُّواْ عَن سَبِيلِهِۦۗ قُلۡ تَمَتَّعُواْ فَإِنَّ مَصِيرَكُمۡ إِلَى ٱلنَّارِ ﴿٣٠﴾", "w": [["كلمة طيبة", "هي: لا إله إلا الله محمد رسول الله."], ["كشجرة طيبة", "هي النخلة."], ["كلمة خبيثة", "هي كلمة الكفر."], ["كشجرة خبيثة", "هي الحنظل."], ["اجتُثّت", "اقتُلعت جثتها، أي جسمها وذاتها."], ["بالقول الثابت", "هو: لا إله إلا الله."], ["وفي الآخرة", "في القبر، فيجيب الملكين عما يسألانه عنه، عن ربه ودينه ونبيه."], ["بدّلوا نعمة الله كفراً", "بدّلوا التوحيد والإسلام بالجحود والشرك."], ["دار البوار", "جهنم."], ["وجعلوا لله أنداداً", "شركاء."]], "m": "ألم تر أيها الرسول كيف ضرب الله مثلاً كلمة طيبة، كلمة الإيمان يقولها المؤمن، كشجرة طيبة هي النخلة، أصلها ثابت في الأرض وفرعها عالٍ في السماء، تعطي ثمرها كل حين: بلحاً وبُسراً ورطباً وتمراً، في الصباح والمساء، بإذن ربها، فكلمة «لا إله إلا الله محمد رسول الله» تثمر للعبد أعمالاً صالحة كل حين، وترفع إلى الله، ويضرب الله الأمثال للناس لعلهم يتذكرون فيؤمنوا. ومثل كلمة الكفر في قلب الكافر كشجرة خبيثة، الحنظل، اقتُلعت من فوق الأرض ما لها من ثبات، ولا تثمر إلا المرارة. يثبّت الله الذين آمنوا بالقول الثابت في الحياة الدنيا مهما كانت الفتن والمحن حتى يموتوا على الإيمان، وفي القبر عندما يسألهم الملكان: من ربك؟ ما دينك؟ من نبيك؟ ويضل الله الظالمين فلا يوفّقهم للقول الثابت لإصرارهم على الشرك وأذيتهم المؤمنين، ويفعل الله ما يشاء بحكم عالية. ألم تر إلى الذين بدّلوا نعمة الله، الإسلام، كفراً فكذّبوا الرسول، وأحلّوا قومهم دار الهلاك جهنم يصلونها وبئس القرار، وجعلوا لله شركاء كاللات والعزى ليَضِلوا ويُضِلّوا عن سبيله؟ قل: تمتّعوا بما أنتم فيه، فإن مصيركم إلى النار.", "h": ["استحسان ضرب الأمثال لتقريب المعاني إلى الأذهان.", "المقارنة بين الإيمان والكفر، وكلمة التوحيد وكلمة الكفر، وما يثمره كل واحد منهما.", "بشرى المؤمن بتثبيت الله تعالى له على إيمانه حتى يموت مؤمناً، وبالنجاة من عذاب القبر حيث يجيب منكراً ونكيراً على سؤالهما إياه بتثبيت الله تعالى له.", "الأمر في قوله تعالى: «تمتعوا» ليس للإباحة ولا للوجوب، وإنما هو للتهديد والوعيد."], "k": "«تؤتي أكلها كل حين بإذن ربها»… شهادتي تثمر كل يوم؛ فما الثمرة التي أخرجتها اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (168, 14, 31, 41, 'سورة إبراهيم ٣١ – ٤١', '«وإن تعدّوا نعمة الله لا تحصوها»، ودعاء إبراهيم ﵇ لمكة وذريته', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 168) = $j$[{"lbl": "الآيات ٣١ – ٣٤", "q": "قُل لِّعِبَادِيَ ٱلَّذِينَ ءَامَنُواْ يُقِيمُواْ ٱلصَّلَوٰةَ وَيُنفِقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خِلَٰلٌ ﴿٣١﴾ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِيَ فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَٰرَ ﴿٣٢﴾ وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَآئِبَيۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ ﴿٣٣﴾ وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومٞ كَفَّارٞ ﴿٣٤﴾", "w": [["لا بيع فيه ولا خلال", "لا شراء فيه يُفتدى به، ولا خُلّة أي صداقة تنفع."], ["دائبين", "جاريين في فلكهما لا يفتران أبداً حتى نهاية الحياة الدنيا."], ["لظلوم كفار", "كثير الظلم لنفسه ولغيره، عظيم الكفر، هذا ما لم يؤمن ويهتد، فإن آمن واهتدى سُلب هذا الوصف منه."]], "m": "لما أمر الله رسوله أن يقول للذين بدّلوا نعمة الله كفراً: تمتعوا فإن مصيركم إلى النار، أمره أن يقول للمؤمنين: أقيموا الصلاة على الوجه الذي شُرعت عليه، بإتمام ركوعها وسجودها، وفي أوقاتها، وفي جماعة، حتى تثمر لهم زكاة النفوس وطهارة الأرواح، وأنفقوا مما رزقناكم سراً وعلانية، من قبل أن يأتي يوم القيامة لا بيع فيه يفتدي به المرء نفسه، ولا صداقة تنفعه. الله الذي خلق السماوات والأرض، وأنزل من السماء ماء المطر فأخرج به من الثمرات والحبوب رزقاً لكم، وسخّر لكم السفن لتجري في البحر بأمره تحملون عليها البضائع وتركبونها، وسخّر لكم الأنهار بالمياه العذبة لتشربوا وتسقوا زروعكم، وسخّر لكم الشمس والقمر دائبين لا يفتران لمنافعكم، وسخّر لكم الليل لتسكنوا والنهار لتعملوا، وآتاكم من كل ما أنتم في حاجة إليه، هذا هو المعبود الحق الذي يجب أن يُعبد وحده، لا تلك الأصنام. وإن تعدّوا نعمة الله لا تحصوها عدّاً بحال، إن الإنسان إذا حُرم الإيمان والهداية لظلوم كثير الظلم، كفار عظيم الكفر.", "h": ["وجوب إقام الصلاة وإيتاء الزكاة، والإكثار من الصدقات لاتّقاء عذاب النار.", "جواز صدقة العلن كصدقة السر، وإن كانت الأخيرة أفضل.", "التعريف بالله عز وجل، إذ معرفة الله تعالى هي التي تثمر الخشية منه تعالى.", "وجوب عبادة الله تعالى، وبطلان عبادة غيره.", "وصف الإنسان بالظلم والكفر وشدتهما، ما لم يؤمن ويستقم على منهج الإسلام."], "k": "«وإن تعدّوا نعمة الله لا تحصوها»… لو بدأت أعدّ نعم هذا اليوم وحده، أين أتوقف؟"}, {"lbl": "الآيات ٣٥ – ٤١", "q": "وَإِذۡ قَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ ﴿٣٥﴾ رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرٗا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ ﴿٣٦﴾ رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ ﴿٣٧﴾ رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِي وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ مِن شَيۡءٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ ﴿٣٨﴾ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ ﴿٣٩﴾ رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ ﴿٤٠﴾ رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ ﴿٤١﴾", "w": [["هذا البلد آمناً", "اجعل مكة بلداً آمناً يأمن كل من دخله."], ["أن نعبد الأصنام", "عن أن نعبد الأصنام."], ["أضللن كثيراً من الناس", "بعبادتهم لها."], ["فمن تبعني فإنه مني", "من اتبعني على التوحيد فهو من أهل ملتي وديني."], ["من ذريتي", "من بعض ذريتي، وهو إسماعيل ﵇ وأمه هاجر."], ["بواد غير ذي زرع", "مكة، إذ لا مزارع فيها ولا حولها يومئذ."], ["تهوي إليهم", "تحنّ إليهم وتميل رغبةً في الحج والعمرة."], ["على الكبر إسماعيل وإسحاق", "مع الكبر، إذ كانت سنّه يوم وُلد إسماعيل تسعاً وتسعين سنة، وولد له إسحاق وسنّه مائة واثنتا عشرة سنة."], ["ولوالديّ", "هذا قبل أن يعرف موت والده على الشرك."], ["يوم يقوم الحساب", "يوم يقوم الناس للحساب."]], "m": "اذكر إذ قال إبراهيم، ولا يذكر ما لم يُوحِ الله إليه، ففيه تقرير لنبوة رسول الله ﷺ: رب اجعل مكة بلداً ذا أمن يأمن من دخله على نفسه وماله، وأبعدني وبنيّ أن نعبد الأصنام، وقد استجاب الله له فلم يكن في أولاده وأولاد أولاده مشرك، رب إنهن أضللن كثيراً من الناس بعبادتهم لها، فمن تبعني على التوحيد فإنه على ملتي، ومن عصاني فإنك غفور رحيم. ربنا إني أسكنت من بعض ذريتي، إسماعيل مع أمه هاجر، بوادٍ لا زرع فيه، مكة، عند بيتك المحرّم، الذي لا يُصاد صيده ولا تُسفك فيه الدماء، ربنا ليقيموا الصلاة، فاجعل قلوب بعض الناس تميل إليهم بالحج والعمرة فتنتقل الأرزاق إلى مكة، وارزقهم من الثمرات لعلهم يشكرون. ربنا إنك تعلم ما نخفي وما نعلن، وهذا من إظهار العبودية والافتقار، وإلا فالله أعلم بحاله وما يصلحه. الحمد لله الذي وهب لي على الكبر إسماعيل وإسحاق، إن ربي لسميع الدعاء. رب اجعلني مقيم الصلاة ومن ذريتي، لأن الصلاة هي الذكر والشكر، ربنا وتقبّل دعاء، ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الناس للحساب.", "h": ["فضل مكة وشرفها، وأنها حرم آمن، أي ذو أمن.", "الخوف من الشرك لخطره، وسؤال الله تعالى الحفظ من ذلك.", "علاقة الإيمان والتوحيد أولى من علاقة الرحم والنسب.", "أهمية إقام الصلاة، وأن من لم يرد أن يصلي لا حق له في الغذاء، ولذا يُعدم إن أصرّ على ترك الصلاة.", "بيان استجابة دعاء إبراهيم ﵇ فيما سأل ربه تعالى فيه.", "وجوب حمد الله وشكره على ما ينعم به على عبده.", "مشروعية الاستغفار للنفس وللمؤمنين والمؤمنات.", "تقرير عقيدة البعث والحساب والجزاء."], "k": "«رب اجعلني مقيم الصلاة ومن ذريتي»… دعاء خليل الله لنفسه وذريته؛ فهل أدعو به لأولادي كل يوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 168;
insert into public.tdb_cards(topic, i, body) select 168, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣١ – ٣٤", "q": "قُل لِّعِبَادِيَ ٱلَّذِينَ ءَامَنُواْ يُقِيمُواْ ٱلصَّلَوٰةَ وَيُنفِقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خِلَٰلٌ ﴿٣١﴾ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزۡقٗا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِيَ فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَٰرَ ﴿٣٢﴾ وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَآئِبَيۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ ﴿٣٣﴾ وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱلۡإِنسَٰنَ لَظَلُومٞ كَفَّارٞ ﴿٣٤﴾", "w": [["لا بيع فيه ولا خلال", "لا شراء فيه يُفتدى به، ولا خُلّة أي صداقة تنفع."], ["دائبين", "جاريين في فلكهما لا يفتران أبداً حتى نهاية الحياة الدنيا."], ["لظلوم كفار", "كثير الظلم لنفسه ولغيره، عظيم الكفر، هذا ما لم يؤمن ويهتد، فإن آمن واهتدى سُلب هذا الوصف منه."]], "m": "لما أمر الله رسوله أن يقول للذين بدّلوا نعمة الله كفراً: تمتعوا فإن مصيركم إلى النار، أمره أن يقول للمؤمنين: أقيموا الصلاة على الوجه الذي شُرعت عليه، بإتمام ركوعها وسجودها، وفي أوقاتها، وفي جماعة، حتى تثمر لهم زكاة النفوس وطهارة الأرواح، وأنفقوا مما رزقناكم سراً وعلانية، من قبل أن يأتي يوم القيامة لا بيع فيه يفتدي به المرء نفسه، ولا صداقة تنفعه. الله الذي خلق السماوات والأرض، وأنزل من السماء ماء المطر فأخرج به من الثمرات والحبوب رزقاً لكم، وسخّر لكم السفن لتجري في البحر بأمره تحملون عليها البضائع وتركبونها، وسخّر لكم الأنهار بالمياه العذبة لتشربوا وتسقوا زروعكم، وسخّر لكم الشمس والقمر دائبين لا يفتران لمنافعكم، وسخّر لكم الليل لتسكنوا والنهار لتعملوا، وآتاكم من كل ما أنتم في حاجة إليه، هذا هو المعبود الحق الذي يجب أن يُعبد وحده، لا تلك الأصنام. وإن تعدّوا نعمة الله لا تحصوها عدّاً بحال، إن الإنسان إذا حُرم الإيمان والهداية لظلوم كثير الظلم، كفار عظيم الكفر.", "h": ["وجوب إقام الصلاة وإيتاء الزكاة، والإكثار من الصدقات لاتّقاء عذاب النار.", "جواز صدقة العلن كصدقة السر، وإن كانت الأخيرة أفضل.", "التعريف بالله عز وجل، إذ معرفة الله تعالى هي التي تثمر الخشية منه تعالى.", "وجوب عبادة الله تعالى، وبطلان عبادة غيره.", "وصف الإنسان بالظلم والكفر وشدتهما، ما لم يؤمن ويستقم على منهج الإسلام."], "k": "«وإن تعدّوا نعمة الله لا تحصوها»… لو بدأت أعدّ نعم هذا اليوم وحده، أين أتوقف؟"}, {"lbl": "الآيات ٣٥ – ٤١", "q": "وَإِذۡ قَالَ إِبۡرَٰهِيمُ رَبِّ ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ ﴿٣٥﴾ رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِيرٗا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّيۖ وَمَنۡ عَصَانِي فَإِنَّكَ غَفُورٞ رَّحِيمٞ ﴿٣٦﴾ رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةٗ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ ﴿٣٧﴾ رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِي وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ مِن شَيۡءٖ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ ﴿٣٨﴾ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ ﴿٣٩﴾ رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ ﴿٤٠﴾ رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ ﴿٤١﴾", "w": [["هذا البلد آمناً", "اجعل مكة بلداً آمناً يأمن كل من دخله."], ["أن نعبد الأصنام", "عن أن نعبد الأصنام."], ["أضللن كثيراً من الناس", "بعبادتهم لها."], ["فمن تبعني فإنه مني", "من اتبعني على التوحيد فهو من أهل ملتي وديني."], ["من ذريتي", "من بعض ذريتي، وهو إسماعيل ﵇ وأمه هاجر."], ["بواد غير ذي زرع", "مكة، إذ لا مزارع فيها ولا حولها يومئذ."], ["تهوي إليهم", "تحنّ إليهم وتميل رغبةً في الحج والعمرة."], ["على الكبر إسماعيل وإسحاق", "مع الكبر، إذ كانت سنّه يوم وُلد إسماعيل تسعاً وتسعين سنة، وولد له إسحاق وسنّه مائة واثنتا عشرة سنة."], ["ولوالديّ", "هذا قبل أن يعرف موت والده على الشرك."], ["يوم يقوم الحساب", "يوم يقوم الناس للحساب."]], "m": "اذكر إذ قال إبراهيم، ولا يذكر ما لم يُوحِ الله إليه، ففيه تقرير لنبوة رسول الله ﷺ: رب اجعل مكة بلداً ذا أمن يأمن من دخله على نفسه وماله، وأبعدني وبنيّ أن نعبد الأصنام، وقد استجاب الله له فلم يكن في أولاده وأولاد أولاده مشرك، رب إنهن أضللن كثيراً من الناس بعبادتهم لها، فمن تبعني على التوحيد فإنه على ملتي، ومن عصاني فإنك غفور رحيم. ربنا إني أسكنت من بعض ذريتي، إسماعيل مع أمه هاجر، بوادٍ لا زرع فيه، مكة، عند بيتك المحرّم، الذي لا يُصاد صيده ولا تُسفك فيه الدماء، ربنا ليقيموا الصلاة، فاجعل قلوب بعض الناس تميل إليهم بالحج والعمرة فتنتقل الأرزاق إلى مكة، وارزقهم من الثمرات لعلهم يشكرون. ربنا إنك تعلم ما نخفي وما نعلن، وهذا من إظهار العبودية والافتقار، وإلا فالله أعلم بحاله وما يصلحه. الحمد لله الذي وهب لي على الكبر إسماعيل وإسحاق، إن ربي لسميع الدعاء. رب اجعلني مقيم الصلاة ومن ذريتي، لأن الصلاة هي الذكر والشكر، ربنا وتقبّل دعاء، ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الناس للحساب.", "h": ["فضل مكة وشرفها، وأنها حرم آمن، أي ذو أمن.", "الخوف من الشرك لخطره، وسؤال الله تعالى الحفظ من ذلك.", "علاقة الإيمان والتوحيد أولى من علاقة الرحم والنسب.", "أهمية إقام الصلاة، وأن من لم يرد أن يصلي لا حق له في الغذاء، ولذا يُعدم إن أصرّ على ترك الصلاة.", "بيان استجابة دعاء إبراهيم ﵇ فيما سأل ربه تعالى فيه.", "وجوب حمد الله وشكره على ما ينعم به على عبده.", "مشروعية الاستغفار للنفس وللمؤمنين والمؤمنات.", "تقرير عقيدة البعث والحساب والجزاء."], "k": "«رب اجعلني مقيم الصلاة ومن ذريتي»… دعاء خليل الله لنفسه وذريته؛ فهل أدعو به لأولادي كل يوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (169, 14, 42, 52, 'سورة إبراهيم ٤٢ – ٥٢', '«ولا تحسبنّ الله غافلاً عما يعمل الظالمون»، و«هذا بلاغ للناس»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 169) = $j$[{"lbl": "الآيات ٤٢ – ٤٦", "q": "وَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ ٱلظَّـٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ ﴿٤٢﴾ مُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَآءٞ ﴿٤٣﴾ وَأَنذِرِ ٱلنَّاسَ يَوۡمَ يَأۡتِيهِمُ ٱلۡعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرۡنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوٓاْ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم مِّن زَوَالٖ ﴿٤٤﴾ وَسَكَنتُمۡ فِي مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓاْ أَنفُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ ﴿٤٥﴾ وَقَدۡ مَكَرُواْ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ ﴿٤٦﴾", "w": [["عما يعمل الظالمون", "المشركون من أهل مكة وغيرهم."], ["تشخص فيه الأبصار", "تنفتح فلا تُغمض لشدة ما ترى من الأهوال."], ["مهطعين مقنعي رؤوسهم", "مسرعين إلى الداعي الذي دعاهم إلى الحشر، رافعين رؤوسهم."], ["وأفئدتهم هواء", "فارغة من العقل لشدة الخوف والفزع."], ["نُجب دعوتك", "على لسان رسولك فنعبدك ونوحّدك."], ["ما لكم من زوال", "عن الدنيا إلى الآخرة."], ["وقد مكروا مكرهم", "مكرت قريش بالنبي ﷺ حيث أرادوا قتله أو حبسه أو نفيه."], ["وإن كان مكرهم لتزول منه الجبال", "لم يكن مكرهم بالذي تزول منه الجبال، فإنه تافه لا قيمة له."]], "m": "في هذا السياق تقوية لرسول الله ﷺ وحمل له على الصبر، والأيام صعبة عليه وعلى أصحابه لتكالب المشركين على أذاهم: ولا تحسبنّ الله غافلاً عما يعمل الظالمون من قومك، إنما يؤخّرهم ليوم تنفتح فيه الأبصار فلا تطرف لشدة الأهوال، مسرعين إلى الداعي رافعين رؤوسهم، لا تنغمض أعينهم من الخوف، وقلوبهم فارغة من الوعي لما أصابها من الفزع. وأنذر الناس يوم يأتيهم العذاب فيقول الذين أشركوا وآذوا المؤمنين: ربنا أخّرنا إلى أجل قريب نُجب دعوتك ونتّبع الرسل، فيقال لهم توبيخاً: أوَلم تكونوا حلفتم من قبل ما لكم من زوال من الدنيا إلى الآخرة؟ وسكنتم في مساكن الذين ظلموا أنفسهم بالشرك والمعاصي، وتبيّن لكم كيف أهلكناهم، وضربنا لكم الأمثال؟ فلا يُجابون ويُقذفون في الجحيم. وقد مكرت قريش برسول الله ﷺ حين قرّروا حبسه أو قتله أو نفيه، وعند الله علم مكرهم وجزاؤهم عليه، ولم يكن مكرهم لتزول منه الجبال، فإنه تافه لا وزن له، فلا تحفل به أيها الرسول، وقد خابوا فيه أشد الخيبة.", "h": ["تأخير العذاب عن الظلمة في كل زمان ومكان لم يكن غفلة عنهم، وإنما هو تأخيرهم إلى يوم القيامة، أو إلى أن يحين الوقت المحدد لأخذهم.", "بيان أهوال يوم القيامة وصعوبة الموقف فيه، حتى يتمنى الظالمون الرجوع إلى الدنيا ليؤمنوا ويطيعوا ويوحّدوا ربهم في عبادته.", "التنديد بالظلم، وبيان عقاب الظالمين بذكر أحوالهم.", "تقرير جريمة قريش في ائتمارها على قتل رسول الله ﷺ."], "k": "«ولا تحسبنّ الله غافلاً عما يعمل الظالمون»… ظلم رأيته ولم يُعاقب صاحبه؛ فهل أوقن أن ربي لا يغفل؟"}, {"lbl": "الآيات ٤٧ – ٥٢", "q": "فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزٞ ذُو ٱنتِقَامٖ ﴿٤٧﴾ يَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَيۡرَ ٱلۡأَرۡضِ وَٱلسَّمَٰوَٰتُۖ وَبَرَزُواْ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ ﴿٤٨﴾ وَتَرَى ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ مُّقَرَّنِينَ فِي ٱلۡأَصۡفَادِ ﴿٤٩﴾ سَرَابِيلُهُم مِّن قَطِرَانٖ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ ﴿٥٠﴾ لِيَجۡزِيَ ٱللَّهُ كُلَّ نَفۡسٖ مَّا كَسَبَتۡۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿٥١﴾ هَٰذَا بَلَٰغٞ لِّلنَّاسِ وَلِيُنذَرُواْ بِهِۦ وَلِيَعۡلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَلِيَذَّكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٥٢﴾", "w": [["إن الله عزيز", "غالب لا يُحال بينه وبين مراده بحال من الأحوال."], ["ذو انتقام", "صاحب انتقام ممن عصاه وعصى رسوله."], ["يوم تُبدّل الأرض", "اذكر يا رسولنا للظالمين يوم تُبدّل الأرض."], ["وبرزوا لله", "خرجوا من القبور لله ليحاسبهم ويجزيهم."], ["مقرّنين", "مشدودة أيديهم وأرجلهم إلى رقابهم."], ["في الأصفاد", "جمع صَفَد، وهو الوثاق من حبل وغيره."], ["سرابيلهم", "قمصانهم التي يلبسونها من قطران."], ["هذا بلاغ", "هذا القرآن بلاغ للناس."], ["أولو الألباب", "أصحاب العقول."]], "m": "ما زال السياق في تسلية الرسول ﷺ والمؤمنين: فلا تحسبنّ الله مخلف وعده رسله، فكما لم يخلف رسله الأولين لا يخلفك، إنه لا بد منجز لك ما وعدك من النصر، فاصبر كما صبر أولو العزم من الرسل، إن الله عزيز غالب، ذو انتقام شديد ممن عصاه وحارب أولياءه. واذكر يوم تُبدّل الأرض غير الأرض والسماوات، وظهروا بعد خروجهم من قبورهم لله الواحد القهار، وترى المجرمين يومئذ مشدودة أيديهم وأرجلهم إلى أعناقهم في الأغلال، أجرموا على أنفسهم بالشرك والظلم ثم على غيرهم، قمصانهم من قطران، مادة سوداء محرقة، أو من نحاس بلغ المنتهى في الحرارة، وتغطي وجوههم النار بلهبها، ليجزي الله كل نفس بما كسبت، إن الله سريع الحساب. هذا القرآن بلاغ للناس من رب الناس، ولينذروا بما فيه من العظات والعبر، وليعلموا بما فيه من الحجج أنما هو إله واحد لا ثاني له، فلا يعبدوا معه غيره، وليتعظ به أصحاب العقول الواعية فيعملوا على إنجاء أنفسهم من غضب الله وعذابه، والفوز برحمته ورضوانه.", "h": ["بيان صدق وعد الله من وعدهم من رسله وأوليائه.", "بيان أحوال المجرمين في العرض وفي جهنم.", "بيان العلة في المعاد الآخر، وهو الجزاء على الكسب في الدنيا.", "قوله تعالى في آخر آية من هذه السورة: «هذا بلاغ للناس ولينذروا به وليعلموا أنما هو إله واحد وليذكّر أولو الألباب» صالحة لأن تكون عنواناً للقرآن الكريم، إذ دلّت على مضمونه كاملاً مع وجازة اللفظ وجمال العبارة."], "k": "«هذا بلاغ للناس»… البلاغ وصلني؛ فماذا أصنع به اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 169;
insert into public.tdb_cards(topic, i, body) select 169, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٢ – ٤٦", "q": "وَلَا تَحۡسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعۡمَلُ ٱلظَّـٰلِمُونَۚ إِنَّمَا يُؤَخِّرُهُمۡ لِيَوۡمٖ تَشۡخَصُ فِيهِ ٱلۡأَبۡصَٰرُ ﴿٤٢﴾ مُهۡطِعِينَ مُقۡنِعِي رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَآءٞ ﴿٤٣﴾ وَأَنذِرِ ٱلنَّاسَ يَوۡمَ يَأۡتِيهِمُ ٱلۡعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرۡنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوٓاْ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم مِّن زَوَالٖ ﴿٤٤﴾ وَسَكَنتُمۡ فِي مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓاْ أَنفُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ ﴿٤٥﴾ وَقَدۡ مَكَرُواْ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ ﴿٤٦﴾", "w": [["عما يعمل الظالمون", "المشركون من أهل مكة وغيرهم."], ["تشخص فيه الأبصار", "تنفتح فلا تُغمض لشدة ما ترى من الأهوال."], ["مهطعين مقنعي رؤوسهم", "مسرعين إلى الداعي الذي دعاهم إلى الحشر، رافعين رؤوسهم."], ["وأفئدتهم هواء", "فارغة من العقل لشدة الخوف والفزع."], ["نُجب دعوتك", "على لسان رسولك فنعبدك ونوحّدك."], ["ما لكم من زوال", "عن الدنيا إلى الآخرة."], ["وقد مكروا مكرهم", "مكرت قريش بالنبي ﷺ حيث أرادوا قتله أو حبسه أو نفيه."], ["وإن كان مكرهم لتزول منه الجبال", "لم يكن مكرهم بالذي تزول منه الجبال، فإنه تافه لا قيمة له."]], "m": "في هذا السياق تقوية لرسول الله ﷺ وحمل له على الصبر، والأيام صعبة عليه وعلى أصحابه لتكالب المشركين على أذاهم: ولا تحسبنّ الله غافلاً عما يعمل الظالمون من قومك، إنما يؤخّرهم ليوم تنفتح فيه الأبصار فلا تطرف لشدة الأهوال، مسرعين إلى الداعي رافعين رؤوسهم، لا تنغمض أعينهم من الخوف، وقلوبهم فارغة من الوعي لما أصابها من الفزع. وأنذر الناس يوم يأتيهم العذاب فيقول الذين أشركوا وآذوا المؤمنين: ربنا أخّرنا إلى أجل قريب نُجب دعوتك ونتّبع الرسل، فيقال لهم توبيخاً: أوَلم تكونوا حلفتم من قبل ما لكم من زوال من الدنيا إلى الآخرة؟ وسكنتم في مساكن الذين ظلموا أنفسهم بالشرك والمعاصي، وتبيّن لكم كيف أهلكناهم، وضربنا لكم الأمثال؟ فلا يُجابون ويُقذفون في الجحيم. وقد مكرت قريش برسول الله ﷺ حين قرّروا حبسه أو قتله أو نفيه، وعند الله علم مكرهم وجزاؤهم عليه، ولم يكن مكرهم لتزول منه الجبال، فإنه تافه لا وزن له، فلا تحفل به أيها الرسول، وقد خابوا فيه أشد الخيبة.", "h": ["تأخير العذاب عن الظلمة في كل زمان ومكان لم يكن غفلة عنهم، وإنما هو تأخيرهم إلى يوم القيامة، أو إلى أن يحين الوقت المحدد لأخذهم.", "بيان أهوال يوم القيامة وصعوبة الموقف فيه، حتى يتمنى الظالمون الرجوع إلى الدنيا ليؤمنوا ويطيعوا ويوحّدوا ربهم في عبادته.", "التنديد بالظلم، وبيان عقاب الظالمين بذكر أحوالهم.", "تقرير جريمة قريش في ائتمارها على قتل رسول الله ﷺ."], "k": "«ولا تحسبنّ الله غافلاً عما يعمل الظالمون»… ظلم رأيته ولم يُعاقب صاحبه؛ فهل أوقن أن ربي لا يغفل؟"}, {"lbl": "الآيات ٤٧ – ٥٢", "q": "فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥٓۚ إِنَّ ٱللَّهَ عَزِيزٞ ذُو ٱنتِقَامٖ ﴿٤٧﴾ يَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَيۡرَ ٱلۡأَرۡضِ وَٱلسَّمَٰوَٰتُۖ وَبَرَزُواْ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ ﴿٤٨﴾ وَتَرَى ٱلۡمُجۡرِمِينَ يَوۡمَئِذٖ مُّقَرَّنِينَ فِي ٱلۡأَصۡفَادِ ﴿٤٩﴾ سَرَابِيلُهُم مِّن قَطِرَانٖ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ ﴿٥٠﴾ لِيَجۡزِيَ ٱللَّهُ كُلَّ نَفۡسٖ مَّا كَسَبَتۡۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿٥١﴾ هَٰذَا بَلَٰغٞ لِّلنَّاسِ وَلِيُنذَرُواْ بِهِۦ وَلِيَعۡلَمُوٓاْ أَنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ وَلِيَذَّكَّرَ أُوْلُواْ ٱلۡأَلۡبَٰبِ ﴿٥٢﴾", "w": [["إن الله عزيز", "غالب لا يُحال بينه وبين مراده بحال من الأحوال."], ["ذو انتقام", "صاحب انتقام ممن عصاه وعصى رسوله."], ["يوم تُبدّل الأرض", "اذكر يا رسولنا للظالمين يوم تُبدّل الأرض."], ["وبرزوا لله", "خرجوا من القبور لله ليحاسبهم ويجزيهم."], ["مقرّنين", "مشدودة أيديهم وأرجلهم إلى رقابهم."], ["في الأصفاد", "جمع صَفَد، وهو الوثاق من حبل وغيره."], ["سرابيلهم", "قمصانهم التي يلبسونها من قطران."], ["هذا بلاغ", "هذا القرآن بلاغ للناس."], ["أولو الألباب", "أصحاب العقول."]], "m": "ما زال السياق في تسلية الرسول ﷺ والمؤمنين: فلا تحسبنّ الله مخلف وعده رسله، فكما لم يخلف رسله الأولين لا يخلفك، إنه لا بد منجز لك ما وعدك من النصر، فاصبر كما صبر أولو العزم من الرسل، إن الله عزيز غالب، ذو انتقام شديد ممن عصاه وحارب أولياءه. واذكر يوم تُبدّل الأرض غير الأرض والسماوات، وظهروا بعد خروجهم من قبورهم لله الواحد القهار، وترى المجرمين يومئذ مشدودة أيديهم وأرجلهم إلى أعناقهم في الأغلال، أجرموا على أنفسهم بالشرك والظلم ثم على غيرهم، قمصانهم من قطران، مادة سوداء محرقة، أو من نحاس بلغ المنتهى في الحرارة، وتغطي وجوههم النار بلهبها، ليجزي الله كل نفس بما كسبت، إن الله سريع الحساب. هذا القرآن بلاغ للناس من رب الناس، ولينذروا بما فيه من العظات والعبر، وليعلموا بما فيه من الحجج أنما هو إله واحد لا ثاني له، فلا يعبدوا معه غيره، وليتعظ به أصحاب العقول الواعية فيعملوا على إنجاء أنفسهم من غضب الله وعذابه، والفوز برحمته ورضوانه.", "h": ["بيان صدق وعد الله من وعدهم من رسله وأوليائه.", "بيان أحوال المجرمين في العرض وفي جهنم.", "بيان العلة في المعاد الآخر، وهو الجزاء على الكسب في الدنيا.", "قوله تعالى في آخر آية من هذه السورة: «هذا بلاغ للناس ولينذروا به وليعلموا أنما هو إله واحد وليذكّر أولو الألباب» صالحة لأن تكون عنواناً للقرآن الكريم، إذ دلّت على مضمونه كاملاً مع وجازة اللفظ وجمال العبارة."], "k": "«هذا بلاغ للناس»… البلاغ وصلني؛ فماذا أصنع به اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;